window.QDATA = {"chapters":{"2":{"title":"Intelligent Agents","deck":"2-Intelligent-Agents.pdf","slides":57},"3":{"title":"Uninformed Search","deck":"3-Search_uninformed.pdf","slides":61},"4":{"title":"Informed Search","deck":"4-Search_informed.pdf","slides":44},"5":{"title":"Games: Adversarial Search","deck":"5-Games.pdf","slides":89},"6":{"title":"Constraint Satisfaction Problems","deck":"6-CSP.pdf","slides":95}},"sources":{"Q26-1":{"label":"Quiz 1 — 1st Semester 2026 (latest)","file":"Quiz/2026/Quiz1_1st_2026.pdf","id":"Q26-1"},"M25-3":{"label":"Midterm — 3rd Semester 2025","file":"Midterms/2025/Midterm_3rd_2025.pdf","id":"M25-3"},"Q25-3":{"label":"Quiz 1 — 3rd Semester 2025","file":"Quiz/2025/Quiz_3rd_2025.pdf","id":"Q25-3"},"F25-3":{"label":"Final — 3rd Semester 2025","file":"Final/2025/Final_3rd_2025.pdf","id":"F25-3"},"M25-2":{"label":"Midterm — 2nd Semester 2025","file":"Midterms/2025/Midterm_2nd_2025.pdf","id":"M25-2"},"Q25-2":{"label":"Quiz — 2nd Semester 2025","file":"Quiz/2025/Quiz_2nd_2025.pdf","id":"Q25-2"},"F25-2":{"label":"Final — 2nd Semester 2025","file":"Final/2025/Final_2nd_2025.pdf","id":"F25-2"},"M25-1":{"label":"Midterm — 1st Semester 2025","file":"Midterms/2025/Midterm_1st_2025.pdf","id":"M25-1"},"F25-1":{"label":"Final — 1st Semester 2025","file":"Final/2025/Final_1st.pdf","id":"F25-1"},"M24-3":{"label":"Midterm — 3rd Semester 2024 (model answer)","file":"Midterms/2024/Mid_3rd_2024_Dr.Hachami,Dr.Duha_MA.pdf","id":"M24-3"},"Q24-3":{"label":"Quiz 1 — 3rd Semester 2024 (model answer)","file":"Quiz/2024/Quiz1-3rd-2024-Dr.Hachemi, Dr.Duha-MA.pdf","id":"Q24-3"},"M24-1":{"label":"Midterm — 1st Semester 2024","file":"Midterms/2024/Midterm_1st_2024.pdf","id":"M24-1"},"Q24-1":{"label":"Quiz 1 — 1st Semester 2024 (model answer)","file":"Quiz/2024/Quiz1_1st_2024.pdf","id":"Q24-1"},"F24-1":{"label":"Final — 1st Semester 2024","file":"Final/2024/Final_1st_2024.pdf","id":"F24-1"},"M23-1":{"label":"Midterm — 1st Semester 2023 (model answer)","file":"Midterms/2023/Midterm_S1_MA.pdf","id":"M23-1"},"Q23-1A":{"label":"Quiz 1 — 1st Semester 2023 (model answer)","file":"Quiz/2023/Quiz1_1st_2023_Model Ans.pdf","id":"Q23-1A"},"Q23-2A":{"label":"Quiz 2 — 1st Semester 2023 (model answer)","file":"Quiz/2023/Quiz2_MA_1st_2023.pdf","id":"Q23-2A"},"F23-1":{"label":"Final — 1st Semester 2023","file":"Final/2023/Final_1st_2023.pdf","id":"F23-1"},"M23-3":{"label":"Midterm — 3rd Semester 2023 (model answer)","file":"Midterms/2023/Mid_3rd_2023_MA.pdf","id":"M23-3"},"Q23-1B":{"label":"Quiz 1 — 3rd Semester 2023 (model answer)","file":"Quiz/2023/Quiz1_3rd_2023_Dr.Hachemi_MA.pdf","id":"Q23-1B"},"Q23-2B":{"label":"Quiz 2 — 3rd Semester 2023 (model answer)","file":"Quiz/2023/Quiz2_3rd_2023_Dr.Hachemi_MA.pdf","id":"Q23-2B"},"F23-3":{"label":"Final — 3rd Semester 2023 (marked copy)","file":"Final/2023/Final_3rd_2023(with Answers).pdf","id":"F23-3"},"M22A":{"label":"Midterm — 1st Semester 2022 (model answer)","file":"Midterms/2022/Mid-CS-CS361-2-22_MA (1).pdf","id":"M22A"},"Q22-1":{"label":"Quiz 1 — 1st Semester 2022 (model answer)","file":"Quiz/2022/QUIZ1_MA.pdf","id":"Q22-1"},"F22-1":{"label":"Final — 1st Semester 2022 (model answer)","file":"Final/2022/Final_2022_1st(Model answers).pdf.pdf","id":"F22-1"},"M22-1":{"label":"Midterm 1 — 2nd Semester 2022 (model answer)","file":"Midterms/2022/Mid1-CS-CS361-2-22_MA.pdf","id":"M22-1"},"M22-2":{"label":"Midterm 2 — 2nd Semester 2022 (model answer)","file":"Midterms/2022/Mid2-CS-CS361-2-22_MA(1).docx","id":"M22-2"},"M21-1":{"label":"Midterm 1 — Fall 2021 (model answer)","file":"Midterms/2021/Mid1-CS-CS340-CS361-Fall2021-ModelAnswer.pdf","id":"M21-1"},"M21-2":{"label":"Midterm 2 — 2nd Semester 2021 (model answer)","file":"Midterms/2021/Mid2-CS-CS361-1-21-ModelAnswer.pdf","id":"M21-2"},"Q21-1":{"label":"Quiz 1 — 2021 (graded student copy)","file":"Quiz/2021/Quiz1_1st_2021_T.AmjadAlamr.pdf","id":"Q21-1"},"Q21-1MA":{"label":"Quiz 1 — 2nd Semester 2021 (model answer)","file":"Quiz/2021/QUIZ1-CS361-MA.docx","id":"Q21-1MA"},"Q21-2A":{"label":"Quiz 2 — 2021 (Blackboard screenshots)","file":"Quiz/2021/Quiz2-2021-t.amjad.pdf","id":"Q21-2A"},"Q21-2B":{"label":"Quiz 2 — 2021 (Blackboard screenshots, set B)","file":"Quiz/2021/Quiz2_2021_T.amjad.pdf","id":"Q21-2B"}},"questions":[{"id":"Q26-1-1-3","ch":2,"sl":"5, 13","tp":"Robot legs = actuators","t":"mcq","q":"In a marathon running robot, the legs represent:","o":["Performance Measure","Environment","Actuators","Sensors"],"a":2,"e":"Slide 5: a robotic agent uses various motors as actuators (a human agent: hands, legs…). The legs are how the robot <b>acts</b> on the environment — <b>actuators</b> (A in PEAS, slide 13).","from":[{"s":"Q26-1","qn":"Q1.3","pg":1}]},{"id":"Q26-1-1-4","ch":2,"sl":"21–23","tp":"LEGO puzzle environment","t":"mcq","q":"The following describe the task environment of a physical LEGO puzzle set:","o":["Deterministic and episodic","Deterministic and sequential","Discrete and dynamic","Continuous and observable"],"a":1,"e":"Placing a brick has a predictable result → <b>deterministic</b> (slide 21). Every brick placed changes which placements are possible later, so decisions affect the future → <b>sequential</b> (slides 22–23, like chess). The puzzle does not change while the agent thinks, so it is not dynamic.","from":[{"s":"Q26-1","qn":"Q1.4","pg":1}]},{"id":"M25-3-1-1","ch":2,"sl":"13","tp":"PEAS","t":"mcq","q":"PEAS in the context of intelligent agents stands for","o":["Problem, Evidence, Analysis, Solution","Performance Measure, Evaluation Function, Actions, States","Performance Measure, Environment, Actuators, Sensors","Problem, Environment, Actuators, Sensors"],"a":2,"e":"Slide 13 (Specifying the task environment): PEAS = <b>P</b>erformance measure, <b>E</b>nvironment, <b>A</b>ctuators, <b>S</b>ensors.","from":[{"s":"M25-3","qn":"Q1.1","pg":1}]},{"id":"Q25-3-1-2","ch":2,"sl":"9, 13","tp":"Football robot: speed = performance measure","t":"mcq","q":"In a football playing robot, speed represents:","o":["Performance measure","Environment","Actuators","Sensors"],"a":0,"e":"Slide 9: the performance measure is the objective criterion for how well the agent behaves (e.g. time taken). How fast the robot plays is a criterion of success — the <b>performance measure</b>. The legs/motors would be actuators, the field the environment.","from":[{"s":"Q25-3","qn":"Q1.2","pg":1}]},{"id":"Q25-3-1-3","ch":2,"sl":"24–27","tp":"Chess without a clock","t":"mcq","q":"The following describes the task environment for a Chess without a clock agent:","o":["Fully observable and dynamic.","Discrete and fully observable.","Deterministic and single agent.","Static and episodic."],"a":1,"e":"Slide 27, column \"chess without a clock\": fully observable Yes, deterministic (strategic), episodic No, static Yes, discrete Yes, single agent No. Only <b>discrete and fully observable</b> is right; it is static (not dynamic), multi-agent, and sequential.","from":[{"s":"Q25-3","qn":"Q1.3","pg":1}]},{"id":"F25-3-1-1","ch":2,"sl":"41–42","tp":"Partially observable: simple reflex fails","t":"mcq","q":"In a partially observable environment, which type of agents are not accurate?","o":["Model-based reflex agents","Goal-based agents","Utility-based agents","Simple reflex agents"],"a":3,"e":"Slide 41: a simple reflex agent <i>must be fully observable to be accurate</i> — it only sees the current percept. Slide 42: model-based agents are the solution to partial observability because they keep an internal state.","from":[{"s":"F25-3","qn":"Q1.1","pg":1},{"s":"Q23-1B","qn":"Q1.4","pg":2}]},{"id":"M25-2-1-1","ch":2,"sl":"52","tp":"Learning agent","t":"mcq","q":"In artificial intelligence, what is the primary function of a learning agent?","o":["To improve its performance based on experience","To mimic human behavior","To follow predefined rules","To react to the environment without learning"],"a":0,"e":"Slide 52 (Learning agents): all agents can improve their performance through learning; the learning element is responsible for making improvements, using feedback from the critic. So a learning agent <b>improves its performance based on experience</b>.","from":[{"s":"M25-2","qn":"Q1.1","pg":4}]},{"id":"M25-2-1-2","ch":2,"sl":"49, 51","tp":"Utility-based agent","t":"mcq","q":"What is the main purpose of a utility-based agent?","o":["To achieve its goals","To react to the environment","To maximize its expected utilities of the action outcomes","To maintain an internal state"],"a":2,"e":"Slides 48–51: goals are only binary (happy / not happy), so a utility-based agent uses a utility function that maps a state to a real number (degree of happiness) and picks the action with the best utility — i.e. it <b>maximizes the expected utility</b> of the outcomes. Achieving goals is the goal-based agent; reacting is the simple reflex agent; keeping an internal state is the model-based agent.","from":[{"s":"M25-2","qn":"Q1.2","pg":4}]},{"id":"Q25-2-1-2","ch":2,"sl":"19–27","tp":"8-puzzle environment","t":"mcq","q":"The following describes the task environment for an 8-Puzzle agent:","o":["Discrete and single agent.","Fully observable and dynamic.","Deterministic and multi-agent.","Static and episodic."],"a":0,"e":"The 8-puzzle has a finite set of tile configurations and moves → <b>discrete</b> (slide 25), and one agent solves it alone, like a crossword → <b>single agent</b> (slide 26). It is static (not dynamic) and sequential (each move affects the next), so B, C and D each contain a wrong property.","from":[{"s":"Q25-2","qn":"Q1.2","pg":2}]},{"id":"M25-1-1-2","ch":2,"sl":"22–23, 26","tp":"Uno: multi-agent, sequential","t":"mcq","q":"The following describe the task environment of the Uno card game:","o":["Multi-agent and episodic","Multi-agent and sequential","Single-agent and episodic","Single-agent and sequential"],"a":1,"e":"Slide 26: an agent playing against other players is in a <b>multi-agent</b> (competitive) environment. Slides 22–23: in a <b>sequential</b> environment the current decision affects future decisions — every card you play changes what you and the others can play next (like chess). Episodic tasks are one-shot decisions such as spotting defective parts.","from":[{"s":"M25-1","qn":"Q1.2","pg":1}]},{"id":"M25-1-1-3","ch":2,"sl":"13–16","tp":"PEAS: the table is the environment","t":"mcq","q":"In a ping-pong (table tennis) playing robot, the table represents:","o":["Actuators","Performance measure","Sensors","Environment"],"a":3,"e":"Slides 13–18 (PEAS): the <b>environment</b> is what the agent operates in — the table, ball and opponent (like the field and ball for the robot soccer player, slide 18). Actuators would be the arm/paddle, sensors the cameras, and the performance measure points won.","from":[{"s":"M25-1","qn":"Q1.3","pg":1}]},{"id":"M25-1-1-4","ch":2,"sl":"52, 55","tp":"Learning agent: problem generator","t":"mcq","q":"The problem generator in the learning agent is responsible for:","o":["Making improvements","Selecting external actions","Gives feedback on how the agent is doing with respect to a fixed performance standard","Suggesting actions that will lead to new and informative experiences."],"a":3,"e":"Slide 52: <b>problem generator</b> = suggests actions to find new states (new, informative experiences — slide 55: e.g. testing the brakes on different road surfaces). Making improvements = learning element; selecting external actions = performance element; feedback against a fixed standard = critic.","from":[{"s":"M25-1","qn":"Q1.4","pg":1}]},{"id":"F22-1-1-2","ch":2,"sl":"52","tp":"Learning element makes improvements","t":"mcq","q":"In a learning agent, the component that is responsible for making improvements is called:","o":["Learning element","Performance element","Critic","Problem generator"],"a":0,"e":"Slide 52: <b>learning element</b> — responsible for making improvements. The performance element selects external actions, the critic gives feedback, and the problem generator suggests exploratory actions.","from":[{"s":"F25-1","qn":"Q1.1","pg":1},{"s":"F22-1","qn":"Q1.2","pg":2}]},{"id":"F22-1-1-10","ch":2,"sl":"24","tp":"Static environment","t":"mcq","q":"If the environment itself does not change with the passage of time, it is called:","o":["dynamic","fully observable","deterministic","static"],"a":3,"e":"Slide 24: if the environment can change while the agent is deliberating it is dynamic; otherwise it is <b>static</b> (e.g. crossword puzzles).","from":[{"s":"F25-1","qn":"Q1.6","pg":2},{"s":"F22-1","qn":"Q1.10","pg":3}]},{"id":"F23-1-1-2","ch":2,"sl":"36","tp":"Simple reflex: current percept","t":"mcq","q":"The action of the Simple reflex agent completely depends upon ____________","o":["Perception history","Current perception","Learning theory","Utility functions"],"a":1,"e":"Slide 36: a simple reflex agent selects an action on the basis of the <b>current percept</b>, ignoring the rest of the percept history.","from":[{"s":"F25-1","qn":"Q1.2","pg":1},{"s":"F23-1","qn":"Q1.2","pg":1}]},{"id":"F23-1-1-6","ch":2,"sl":"9, 13","tp":"Dish-cleaning agent: performance measure","t":"mcq","q":"In a dish-cleaning agent, cleaning all dishes while minimizing the required time is an example of:","o":["Environment","Actuators","Sensors","Performance measure"],"a":3,"e":"Slide 9: the performance measure is an objective criterion for success — e.g. for the vacuum agent, the amount of dirt cleaned and the time taken. Cleaning all dishes in the least time is the <b>performance measure</b> (P in PEAS, slide 13).","from":[{"s":"F25-1","qn":"Q1.8","pg":2},{"s":"F23-1","qn":"Q1.6","pg":1}]},{"id":"M22-1-1-2","ch":2,"sl":"20, 27","tp":"Crossword: fully observable","t":"mcq","q":"The environment type of a Crossword Puzzle is:","o":["Partially Observable.","Fully Observable.","All of the above","None of the above."],"a":1,"e":"Slide 27's table: crossword puzzle — fully observable: <b>Yes</b> (also deterministic, static, discrete, single-agent). The whole grid and clues are visible (slide 20).","from":[{"s":"Q24-3","qn":"Q1.1","pg":1},{"s":"M22-1","qn":"Q1.2","pg":2}]},{"id":"Q24-3-1-2","ch":2,"sl":"36, 42","tp":"Model-based vs simple reflex","t":"mcq","q":"What differentiates a model-based reflex agent from a simple reflex agent?","o":["A model-based agent relies only on current understanding.","A simple reflex agent only looks at percept history.","A model-based agent can incorporate percept history.","A simple reflex agent is more sophisticated."],"a":2,"e":"Slide 36: the simple reflex agent ignores the percept history. Slide 42: the model-based agent maintains an internal state <b>that depends on the percept history</b>, updated with knowledge of how the world changes.","from":[{"s":"Q24-3","qn":"Q1.2","pg":1},{"s":"Q23-1A","qn":"Q1.4","pg":2}]},{"id":"M24-1-1-1","ch":2,"sl":"36, 39–40","tp":"Simple reflex agent","t":"mcq","q":"Which type of agent operates by mapping percepts directly to actions?","o":["Simple reflex agent","Model-based agent","Goal-based agent","Utility-based agent"],"a":0,"e":"Slides 36 and 39–40: a <b>simple reflex agent</b> selects its action from the current percept alone, using condition-action rules (if car-in-front-is-braking then initiate-braking). Model-based agents also keep an internal state; goal- and utility-based agents also consider goals or utility.","from":[{"s":"M24-1","qn":"Q1.1","pg":1}]},{"id":"M24-1-1-2","ch":2,"sl":"49","tp":"Role of the utility function","t":"mcq","q":"What role does a \"utility function\" play in AI agents?","o":["It determines the speed of the agent","It defines the agent's learning algorithm","It measures how desirable a given state is","It controls the agent's physical movements"],"a":2,"e":"Slide 49: a utility function maps a state onto a real number that describes the associated <b>degree of happiness</b> — how desirable the state is — and helps decide between conflicting goals (like speed and safety).","from":[{"s":"M24-1","qn":"Q1.2","pg":1}]},{"id":"Q24-1-1-1","ch":2,"sl":"20–21, 29","tp":"Robot soccer environment","t":"mcq","q":"Which of the following best describes the environment for Robot Soccer according to AI terminology?","o":["Fully observable and deterministic.","Partially observable and deterministic.","Fully observable and stochastic.","Partially observable and stochastic."],"a":3,"e":"Slide 29 (exercise answer): robot soccer is multi-agent, continuous, dynamic, sequential, <b>stochastic</b> and <b>partially observable</b> — the robot cannot see the whole field and other players move unpredictably.","from":[{"s":"Q24-1","qn":"Q1.1","pg":1}]},{"id":"Q24-1-1-2","ch":2,"sl":"18","tp":"Mars rover accelerometers = sensors","t":"mcq","q":"In an autonomous Mars rover, accelerometers represent:","o":["Sensors","Actuators","Performance measure","Environment"],"a":0,"e":"Slide 18 (PEAS exercise): the Mars rover's <b>sensors</b> are camera, touch sensors, accelerometers, orientation sensors, wheel and radio receiver. Wheels/legs and the radio transmitter are actuators.","from":[{"s":"Q24-1","qn":"Q1.2","pg":1}]},{"id":"M23-1-1A-3","ch":2,"sl":"9, 12","tp":"Performance measure of a self-driving car","t":"mcq","q":"In designing a self-driving car system, which of the following does NOT represent a performance measure for the rational agent?","o":["The average speed at which the car travels.","The color of the car's exterior.","The number of accidents.","The fuel efficiency of the car."],"a":1,"e":"Slide 9: the performance measure is an objective criterion for the success of the agent's behaviour. Slide 12: for a self-driving car — drive fast or save fuel (speed, fuel, safety). The <b>colour of the car</b> has nothing to do with how well the agent drives.","from":[{"s":"M23-1","qn":"Q1 A.3","pg":2}]},{"id":"M23-1-1A-4","ch":2,"sl":"20–26","tp":"Stock trading environment","t":"mcq","q":"Within a dynamic stock trading system where multiple traders interact, which option best characterizes the agent-environment type?","o":["Single agent, fully observable environment, discrete, and static","Multiple agents, partially observable, continuous, and dynamic","Multiple agents, fully observable, discrete, and dynamic","Single agent, partially observable environment, continuous, and static"],"a":1,"e":"Multiple traders → <b>multi-agent</b> (slide 26). A trader cannot see the other traders' plans and information → <b>partially observable</b> (slide 20). Prices and time vary continuously → <b>continuous</b> (slide 25). The market changes while the agent deliberates → <b>dynamic</b> (slide 24).","from":[{"s":"M23-1","qn":"Q1 A.4","pg":2}]},{"id":"M23-1-1A-6","ch":2,"sl":"4–5","tp":"Actuator in a video game","t":"mcq","q":"In a video game where a player controls a character, which of the following represents a possible actuator?","o":["The speaker","The keyboard or controller","The character","The monitor"],"a":1,"e":"Slide 4: an agent acts on its environment through actuators. The player acts on the game world through the <b>keyboard or controller</b> — that is how its actions reach the environment (slide 5: hands and other body parts / output devices act). The monitor and speaker are how the player perceives the game, i.e. sources for its sensors. The model answer is (b).","nb":"Model answer: (b). Which device is the actuator depends on whose point of view you take; the key takes the player's.","from":[{"s":"M23-1","qn":"Q1 A.6","pg":2}]},{"id":"Q23-1A-1-1","ch":2,"sl":"5, 13","tp":"Siri speaker = actuator","t":"mcq","q":"In a personal assistant agent like Siri and Alexa, the speaker represents:","o":["Sensors","Actuators","Performance measure","Percept"],"a":1,"e":"Slide 5: a virtual agent uses signals and output devices as actuators. The speaker is how the assistant <b>acts</b> (talks back) — an <b>actuator</b>. The microphone would be a sensor.","from":[{"s":"Q23-1A","qn":"Q1.1","pg":2}]},{"id":"Q23-1A-1-2","ch":2,"sl":"9","tp":"Rational agent definition","t":"mcq","q":"Which of the following options best describes a rational agent?","o":["An agent that always takes actions based on its emotions and instincts.","An agent that acts randomly without considering the environment or its goals.","An agent that consistently selects actions that maximize its performance measure based on the percept sequence and built-in knowledge.","An agent that follows a fixed set of rules and actions regardless of the circumstances."],"a":2,"e":"Slide 9: for each possible percept sequence, a rational agent selects an action expected to <b>maximize its performance measure</b>, given the evidence from the percept sequence and its built-in knowledge.","from":[{"s":"Q23-1A","qn":"Q1.2","pg":2}]},{"id":"Q23-1A-1-3","ch":2,"sl":"20, 25","tp":"Search-and-rescue drone environment","t":"mcq","q":"The environment of a drone agent searching for a missing person is:","o":["episodic","partially observable","continuous","both answers b and c are correct"],"a":3,"e":"The drone only sees part of the area at a time → <b>partially observable</b> (slide 20); position, speed and time vary continuously → <b>continuous</b> (slide 25, like taxi driving). Its decisions affect where it searches next, so it is sequential, not episodic.","from":[{"s":"Q23-1A","qn":"Q1.3","pg":2}]},{"id":"Q23-1A-1-5","ch":2,"sl":"52","tp":"Learning element uses critic feedback","t":"mcq","q":"The _____ takes the feedback from the critic element and figures out how to make the action better next time.","o":["Critic element","Learning element","Problem generator","Performance element"],"a":1,"e":"Slide 52: the critic gives feedback to the <b>learning element</b>, which is responsible for making improvements (slide 54: it formulates a rule that the left turn was bad and modifies the performance element).","from":[{"s":"Q23-1A","qn":"Q1.5","pg":2}]},{"id":"Q23-1A-1-6","ch":2,"sl":"24, 26","tp":"Cooperative timed game","t":"mcq","q":"The game environment in which players need to cooperate to reach the goal in the shortest possible time is:","o":["multiagent","Semidynamic","cooperative","All the above answers are correct."],"a":3,"e":"Several players → <b>multi-agent</b>, and they help each other → <b>cooperative</b> (slide 26). Racing the clock means the score changes with time while the world itself does not → <b>semidynamic</b> (slide 24, like chess with a clock). <b>All the above</b>.","from":[{"s":"Q23-1A","qn":"Q1.6","pg":2}]},{"id":"Q23-1B-1-1","ch":2,"sl":"9, 12","tp":"Self-driving car: safety","t":"mcq","q":"In an autonomous vehicle agent, safety represents:","o":["Sensors","Actuators","Performance measure","Percept"],"a":2,"e":"Slides 9 and 12: the performance measure is the criterion for success — for a self-driving car: safe, fast, fuel-efficient driving. <b>Safety</b> is a performance measure.","from":[{"s":"Q23-1B","qn":"Q1.1","pg":2}]},{"id":"Q23-1B-1-3","ch":2,"sl":"24, 27","tp":"Chess with a clock: semi-dynamic","t":"mcq","q":"The environment of a chess game with a clock is:","o":["dynamic","semi-dynamic","static","episodic"],"a":1,"e":"Slide 24: semidynamic = the environment does not change with time but the agent's performance score does — e.g. <b>chess played with a clock</b>. Slide 27's table agrees (Static: Semi).","from":[{"s":"Q23-1B","qn":"Q1.3","pg":2}]},{"id":"Q23-1B-1-9","ch":2,"sl":"21","tp":"Deterministic environment","t":"mcq","q":"An environment is deterministic if:","o":["there is a unique mapping from one state to another state for a given action","the agent can see at any time when deliberating the whole environment","there are several mappings from one state for a given action","all of the above."],"a":0,"e":"Slide 21: deterministic = the next state is completely determined by the current state and the action — a <b>unique</b> result. Option B describes fully observable; option C describes stochastic.","from":[{"s":"Q23-1B","qn":"Q1.9","pg":3}]},{"id":"Q22-1-1-1","ch":2,"sl":"24–25","tp":"Unchanging, distinct percepts: static discrete","t":"mcq","q":"When an environment is unchanged and has a limited number of distinct, clearly defined percepts and actions, it is:","o":["Semi-dynamic discrete","Static discrete","Dynamic continuous","None of the above"],"a":1,"e":"Slide 24: an environment that does not change while the agent deliberates is <b>static</b>. Slide 25: a limited number of distinct, clearly defined percepts and actions is <b>discrete</b>.","from":[{"s":"Q22-1","qn":"Q1.1","pg":2}]},{"id":"Q22-1-1-2","ch":2,"sl":"18","tp":"Online shopping agent: performance measure","t":"mcq","q":"In an online shopping agent, buying the requested items and minimizing the cost are examples of:","o":["Performance measure","Environment","Actuators","Sensors"],"a":0,"e":"Slide 18 (internet book-shopping agent): performance measure = <b>obtain requested/interesting books, minimize expenditure</b>.","from":[{"s":"Q22-1","qn":"Q1.2","pg":2}]},{"id":"Q22-1-1-3","ch":2,"sl":"49","tp":"Conflicting goals: utility-based","t":"mcq","q":"Which agent type selects among multiple or conflicting goals?","o":["Learning agents","Goal-based agents","Utility-based agents","None of the above"],"a":2,"e":"Slide 49: the utility function lets the agent <b>select among multiple or conflicting goals</b> (like speed and safety) — the <b>utility-based agent</b>. Goals alone are only binary (slide 48).","from":[{"s":"Q22-1","qn":"Q1.3","pg":2}]},{"id":"Q22-1-1-4","ch":2,"sl":"52, 54","tp":"Critic belongs to the learning agent","t":"mcq","q":"Which agent type has a critic module that observes the world and passes information along to the learning element?","o":["Goal-based agents","Utility-based agents","Learning agents","None of the above"],"a":2,"e":"Slides 52 and 54: the critic is one of the four components of a <b>learning agent</b>; it observes the world and gives feedback to the learning element.","from":[{"s":"Q22-1","qn":"Q1.4","pg":2}]},{"id":"Q22-1-1-5","ch":2,"sl":"20, 25–26","tp":"Tennis agent environment","t":"mcq","q":"The environment of a tennis-playing agent is:","o":["fully observable","discrete","single agent","All the above answers are correct"],"a":0,"e":"The model answer is <b>(a) fully observable</b>: the agent can see the whole court, the ball and the opponent. Tennis is <i>not</i> discrete (ball position and speed are continuous, slide 25) and <i>not</i> single-agent (there is an opponent, slide 26), so B, C and D are wrong.","nb":"Model answer: (a). Some argue the opponent's intentions are hidden, but the court state itself is visible — and the other options are clearly wrong.","from":[{"s":"Q22-1","qn":"Q1.5","pg":2}]},{"id":"Q22-1-1-8","ch":2,"sl":"11","tp":"Autonomous agent","t":"mcq","q":"The agent whose behavior is determined by its own experience is called ______ agent.","o":["single agent","omniscience","autonomous","simple reflex"],"a":2,"e":"Slide 11: <i>an agent is <b>autonomous</b> if its behavior is determined by its own experience</i> (with the ability to learn and adapt).","from":[{"s":"Q22-1","qn":"Q1.8","pg":3}]},{"id":"Q22-1-1-9","ch":2,"sl":"26","tp":"Multi-agent: competitive or cooperative","t":"mcq","q":"In a multi-agent environment, the agents can be:","o":["competitive","cooperative","both (a) and (b) are correct","All the above answers are incorrect"],"a":2,"e":"Slide 26: multi-agent environments can be competitive (chess), cooperative (taxi), or partially cooperative/competitive — <b>both</b>.","from":[{"s":"Q22-1","qn":"Q1.9","pg":3}]},{"id":"M22-1-1-1","ch":2,"sl":"36","tp":"Simple reflex agent: current percept","t":"mcq","q":"The simple reflex agent selects an action based on?","o":["The current percept ignoring the history","The current percept plus history","The goal and the cost to reach it.","None of the above"],"a":0,"e":"Slide 36: a simple reflex agent selects an action on the basis of the <b>current percept, ignoring the rest of the percept history</b>.","from":[{"s":"M22-1","qn":"Q1.1","pg":2}]},{"id":"M21-1-1-1","ch":2,"sl":"20, 27","tp":"Fully observable example","t":"mcq","q":"An example of an agent in a fully observable environment is:","o":["Self-driving car.","drone.","chess playing agent."],"a":2,"e":"Slide 27: chess (with or without a clock) is <b>fully observable</b> — the whole board is visible. Taxi driving is not; a self-driving car or a drone cannot sense the complete state of the world (slide 20).","from":[{"s":"M21-1","qn":"Q1.1","pg":2}]},{"id":"M21-1-1-7","ch":2,"sl":"21","tp":"Stochastic vs deterministic","t":"tf","q":"An agent's environment is said to be stochastic if the next state is completely determined by the current state and the agent's action.","a":1,"e":"Slide 21: if the next state is completely determined by the current state and the action, the environment is <b>deterministic</b>; otherwise it is stochastic (e.g. taxi driving). <b>False</b>.","from":[{"s":"M21-1","qn":"Q1.7","pg":3}]},{"id":"Q21-1-1","ch":2,"sl":"20, 36, 42; ch3 9","tp":"Timetable agent: goals, observability, agent type","t":"short","q":"Deema wants to arrange her university timetable so that she has <b>8 credit hours</b>, <b>at least two CS courses</b> and <b>a day off</b>. You design an agent that gives her several timetable options from this list:<div class=\"tbl\"><table class=\"mini\"><tr><th>Course-section</th><th>Days</th><th>Time</th><th>Credits</th></tr><tr><td>CS340-271</td><td>Mon-Wed</td><td>1-2</td><td>4</td></tr><tr><td>CS340-272</td><td>Mon-Wed</td><td>3-4</td><td>4</td></tr><tr><td>CS330-271</td><td>Sun-Tue</td><td>1-2</td><td>4</td></tr><tr><td>CS330-272</td><td>Sun-Tue</td><td>3-4</td><td>4</td></tr><tr><td>CS390-271</td><td>Sun</td><td>5</td><td>1</td></tr><tr><td>CS390-272</td><td>Wed</td><td>3</td><td>1</td></tr><tr><td>CS390-272</td><td>Thu</td><td>5</td><td>1</td></tr></table></div>a. Give two examples of goal states.<br>b. Is the environment observable or unobservable? Explain.<br>c. Is the timetable-creating agent a simple reflex agent? Explain.","a":"a. Any CS340 section + any CS330 section = 2 CS courses, 8 credit hours, classes only Sun–Wed → <b>Thursday off</b>. E.g. <b>CS340-271 + CS330-271</b>, or <b>CS340-272 + CS330-272</b> (also the two mixed pairs).<br>b. <b>Fully observable</b> — the agent knows the whole course list (days, times, credits) at every step.<br>c. <b>No.</b> A simple reflex agent acts only on the current percept; this agent must remember the courses already chosen (credits so far, days used) and aim at a goal, so it is a model-based / goal-based agent.","e":"Uninformed search slide 9: a goal state is defined by the goal test (here: 8 credits, ≥ 2 CS courses, one free day). Agents slide 20: fully observable = the sensors give the complete state. Slides 36 and 42: a simple reflex agent ignores the percept history; a model-based agent keeps an internal state; goal-based agents (slide 45) choose actions that reach a goal.","nb":"Graded student copy; the answer above is ours, written in the same way as the student's accepted answers.","from":[{"s":"Q21-1","qn":"Q1","pg":1}]},{"id":"Q21-1-3","ch":2,"sl":"13, 19–26","tp":"PEAS: tank defence agent","t":"short","q":"To design any artificial agent, its rationality depends on specifying PEAS. Define PEAS for: an agent that should plan and arrange the locations of <b>tanks in the battlefield</b> to guarantee the defence of strategic locations, before and during the battle. Also give the environment type.","a":"<b>P</b>: strategic locations defended, battle won, tanks kept safe.<br><b>E</b>: battlefield, own tanks, enemy forces, terrain, strategic locations.<br><b>A</b>: commands to move/position tanks (wheels/tracks), weapons.<br><b>S</b>: cameras/radar, GPS, distance and angle measurements between tanks, communication.<br>Environment: <b>partially observable, stochastic, sequential, dynamic, continuous, multi-agent</b>.","e":"Slide 13: PEAS. Slides 19–27: battle is the hard case — the enemy is hidden (partially observable), outcomes are uncertain (stochastic), decisions affect later ones (sequential), the situation changes while planning (dynamic), positions are continuous, and there are opponents (multi-agent).","nb":"Graded student copy (2.5/3 for PEAS, environment marked partly wrong); this answer corrects it.","from":[{"s":"Q21-1","qn":"Q1 (p. 2)","pg":2}]},{"id":"Q21-1MA-1","ch":2,"sl":"13, 18, 20–26, 29","tp":"PEAS of a football-playing robot","t":"short","q":"Describe the PEAS aspects of a <b>football-playing robot</b>, and its environment type (fully / partially observable, episodic / sequential, static / dynamic, single / multi-agent).","a":"<b>Performance measure</b>: goals scored, correct passes, winning, speed.<br><b>Environment</b>: football field, ball, own team members, opponents, referee, audience.<br><b>Actuators</b>: legs (for running and kicking), arms, motors.<br><b>Sensors</b>: camera, sound sensors, motion sensors, collision/touch sensors.<br><b>Environment type</b>: <b>partially observable</b>, <b>sequential</b>, <b>dynamic</b>, <b>multi-agent</b> (and stochastic, continuous).","e":"Slide 13: PEAS = Performance measure, Environment, Actuators, Sensors. Slides 18 and 29 give the robot soccer player: winning game, goals for/against · field, ball, own team, other team, own body · devices (e.g. legs) for locomotion and kicking · camera, touch sensors, accelerometers, orientation sensors; and its environment is multi-agent, continuous, dynamic, sequential, stochastic, partially observable.","from":[{"s":"Q21-1MA","qn":"Q1","pg":1}]},{"id":"M25-3-1-2","ch":3,"sl":"22","tp":"What the fringe holds","t":"mcq","q":"The fringe contains","o":["Only leaf nodes","Only expanded nodes","Expanded nodes and leaf nodes","None of the above"],"a":0,"e":"Slide 22: the fringe (frontier) is <i>the set of all nodes at the end of all visited paths</i> — the generated nodes that are waiting to be expanded, i.e. the leaves of the current search tree. Expanded nodes have already left the fringe (in graph search they go to the closed list, slide 59).","from":[{"s":"M25-3","qn":"Q1.2","pg":1}]},{"id":"M25-3-1-3","ch":3,"sl":"40","tp":"UCS fringe = priority queue","t":"mcq","q":"In Uniform Cost Search, the fringe is implemented as a","o":["Heap","Priority Queue","Queue","Stack"],"a":1,"e":"Slide 40: UCS stores the frontier as a <b>priority queue ordered by g(n)</b> (path cost) instead of the simple FIFO queue used by BFS. (A heap is one way to build a priority queue, but the slide's answer is the priority queue.)","from":[{"s":"M25-3","qn":"Q1.3","pg":1}]},{"id":"M25-3-1-4","ch":3,"sl":"44–45","tp":"DFS fringe = stack (LIFO)","t":"mcq","q":"In Depth First Search, the fringe is implemented as a","o":["Heap","Priority Queue","Queue","Stack"],"a":3,"e":"Slides 44–45: DFS enqueues nodes in LIFO (last-in, first-out) order — successors are put at the front. A LIFO queue is a <b>stack</b>. (BFS uses a FIFO queue, UCS a priority queue.)","from":[{"s":"M25-3","qn":"Q1.4","pg":1}]},{"id":"F25-3-1-2","ch":3,"sl":"37, 57","tp":"Least memory: DFS","t":"mcq","q":"Among the following search strategies, which one is less memory consuming?","o":["BFS","UCS","DFS","None of the above"],"a":2,"e":"Slide 57: DFS needs only O(bm) space — linear. BFS keeps every node, O(b<sup>d+1</sup>) (slide 37), and UCS stores the whole priority queue as well (slide 43).","from":[{"s":"F25-3","qn":"Q1.2","pg":1}]},{"id":"F25-3-1-3","ch":3,"sl":"38, 40, 42, 57","tp":"Optimal with equal costs: BFS and UCS","t":"mcq","q":"Select the pair of optimal search strategies for solving searching problems with equal action costs.","o":["BFS & DFS","BFS & UCS","DFS & UCS","None of the above"],"a":1,"e":"Slide 38: BFS is optimal if all step costs are equal. Slide 42: UCS is optimal for positive costs (and slide 40: it equals BFS when costs are equal). DFS is never guaranteed optimal (slide 57). So <b>BFS & UCS</b>.","from":[{"s":"F25-3","qn":"Q1.3","pg":1}]},{"id":"Q25-2-1-3","ch":3,"sl":"9, 11","tp":"State space of Sudoku","t":"mcq","q":"Consider the Sudoku problem: fill a 9×9 grid with digits so that each row, column and 3×3 subgrid contains all the digits from 1 to 9. Which of the following describes the state space of the Sudoku problem?","o":["The sequence of filling the cells of the grid.","The initial and final states of the grid.","The number of empty cells in the grid.","All possible combinations of digits in the 9×9 grid."],"a":3,"e":"Slide 9: the state space is <b>the set of possible states</b> the environment can be in — here every possible way the grid can be filled. A sequence of fillings is a path (slide 10), and the initial/final states are just two members of the state space.","from":[{"s":"Q25-2","qn":"Q1.3","pg":2}]},{"id":"F25-2-TF1","ch":3,"sl":"42","tp":"UCS completeness","t":"tf","q":"UCS is complete as long as the branching factor is finite and the step costs are positive.","a":0,"e":"Uninformed search slide 42: UCS is complete <i>if b is finite and all step costs are positive</i> (zero-cost loops could trap it). <b>True</b>.","from":[{"s":"F25-2","qn":"Q2.1","pg":3}]},{"id":"F25-2-M1","ch":3,"sl":"25","tp":"Branching factor of a game world","t":"mcq","q":"An AI agent is exploring a game world. At each location, the agent can do one of the following actions: Move North, Move South, Move East, Move West, Stay in the same position. The game world is represented as a graph with 500 possible states. The branching factor of this game world:","o":["500","5","2500","500!"],"a":1,"e":"Slide 25: the branching factor b is the number of children of each node — the number of actions available in a state. Here every location has <b>5</b> actions. The number of states (500) is the size of the state space, not b.","from":[{"s":"F25-2","qn":"MCQ 1","pg":7}]},{"id":"M25-1-1-5","ch":3,"sl":"10","tp":"Solution quality = path cost","t":"mcq","q":"In a well-defined problem, a <b>Solution quality</b> is measured by:","o":["The path from the initial state to a goal state.","The path cost function.","a state space that can feasibly be explored.","None of the above."],"a":1,"e":"Uninformed search, slide 10: <i>solution quality is measured by the path cost</i> (the sum of the action costs), and the optimal solution has the lowest path cost. The path from the initial state to a goal is the definition of a <i>solution</i>, not its quality.","from":[{"s":"M25-1","qn":"Q1.5","pg":1}]},{"id":"M25-1-1-8","ch":3,"sl":"9, 11","tp":"State space","t":"mcq","q":"The set of all states reachable from the initial state is called:","o":["Fringe","Path","State space","Heuristic space"],"a":2,"e":"Slide 9: the <b>state space</b> is the set of possible states the environment can be in; slide 11 represents it as a graph whose vertices are states and edges are actions. The fringe is only the set of generated-but-unexpanded nodes (slide 22), and a path is one sequence of states (slide 10).","from":[{"s":"M25-1","qn":"Q1.8","pg":2}]},{"id":"M25-1-1-9","ch":3,"sl":"25","tp":"Branching factor","t":"mcq","q":"The branching factor (b) is defined as:","o":["Number of total nodes in memory","Number of children each node has","Maximum depth of the tree","Number of goal states"],"a":1,"e":"Slide 25: b = branching factor = <b>the number of children at each node</b> (an average if it is not uniform). The maximum depth of the state space is m (slide 30).","from":[{"s":"M25-1","qn":"Q1.9","pg":2}]},{"id":"M25-1-1-10","ch":3,"sl":"40","tp":"Priority queue by g(n) = UCS","t":"mcq","q":"Which search uses a <b>priority queue ordered by path cost g(n)</b>?","o":["Depth-First Search","Breadth-First Search","Uniform Cost Search","Greedy Search"],"a":2,"e":"Slide 40: <b>UCS</b> stores the frontier as a priority queue ordered by g(n). Greedy search orders by h(n) (informed search, slide 5); BFS uses FIFO, DFS uses LIFO.","from":[{"s":"M25-1","qn":"Q1.10","pg":2}]},{"id":"Q24-3-1-3","ch":3,"sl":"44–45","tp":"LIFO stack = DFS","t":"mcq","q":"Which search is implemented with an empty (Last-In-First-Out) stack?","o":["BFS","DFS","UCS","GBFS"],"a":1,"e":"Slides 44–45: DFS enqueues nodes in <b>LIFO</b> order — the fringe is a stack. BFS uses FIFO; UCS and GBFS use priority queues.","from":[{"s":"Q24-3","qn":"Q1.3","pg":1}]},{"id":"M24-1-1-3","ch":3,"sl":"40–42","tp":"UCS expansion order","t":"mcq","q":"Given the search graph in the figure, where S is the start node and G is the goal state. Arcs are labelled with the cost of traversing them. When placing expanded child nodes on the fringe with the same cost, assume that the child nodes are placed in <i>alphabetical</i> order. What are the expanded nodes in order if we apply Uniform Cost Search (UCS)?","o":["S→A→B→D","S→A→C→D","S→A→C→D→B","S→A→C→B→D"],"img":"M24-1-1-3.jpg","a":2,"e":"UCS always expands the cheapest node g(n) (slide 40):<br>• S(0) → fringe A(1), G(12)<br>• A(1) → B(4), C(2)<br>• C(2) → D(3), G(4)<br>• D(3) → G(6) (worse than G(4))<br>• B(4) and G(4) tie; alphabetical order puts B first → expand B<br>• G(4) is selected → goal (path S-A-C-G, cost 4).<br>Expanded: <b>S, A, C, D, B</b>.","from":[{"s":"M24-1","qn":"Q1.3","pg":1}]},{"id":"M24-1-1-6","ch":3,"sl":"30","tp":"Completeness","t":"mcq","q":"A searching algorithm is complete if:","o":["It is guaranteed to return a solution when one exists","It is not guaranteed to return a solution when one exists","It returns more solutions, but not an optimal one","It guarantees to return more optimal solutions"],"a":0,"e":"Slide 30: <b>completeness</b> — does it always find a solution if one exists? (Optimality is the separate question of whether it finds a least-cost solution.)","from":[{"s":"M24-1","qn":"Q1.6","pg":2},{"s":"Q22-1","qn":"Q1.7","pg":2}]},{"id":"F24-1-2-6","ch":3,"sl":"32–33","tp":"BFS fringe order","t":"tf","q":"In BFS, the nodes are arranged in the fringe according to decreasing order of the depth of the node.","a":1,"e":"Slides 32–33: BFS expands all nodes at depth i before depth i + 1 — FIFO, <b>increasing</b> depth. Decreasing depth is DFS. <b>False</b>.","from":[{"s":"F24-1","qn":"Q2.6","pg":5}]},{"id":"M23-1-1A-1","ch":3,"sl":"37–39","tp":"BFS: space is the bigger problem","t":"mcq","q":"The biggest problem in the breadth first search (BFS) algorithm is:","o":["its space complexity","its time complexity","finding the solution if one exists.","finding the best solution if one exists."],"a":0,"e":"Slide 37: BFS keeps every node of the fringe in memory, O(b<sup>d+1</sup>) — <i>space is the bigger problem (more than time)</i>. Slide 39's table shows memory running out long before time does.","from":[{"s":"M23-1","qn":"Q1 A.1","pg":2}]},{"id":"Q23-1B-1-6","ch":3,"sl":"22, 24","tp":"What tree search keeps in memory","t":"mcq","q":"Tree-search strategies keep in memory during the search for a path solution:","o":["all nodes of the tree-search","only some nodes at some depth of the tree-search","only the leaf nodes of the tree-search","all of the above."],"a":2,"e":"Slides 22 and 24: the generic tree search stores the <b>fringe</b> — the set of nodes at the end of all visited paths, i.e. the <b>leaf nodes</b> waiting to be expanded.","from":[{"s":"Q23-1B","qn":"Q1.6","pg":3}]},{"id":"Q23-1B-1-7","ch":3,"sl":"30","tp":"Time complexity measured in nodes","t":"mcq","q":"The time complexity of a tree-search strategy is evaluated in terms of","o":["the number of expanded nodes","the cost of the path solution","the height of the tree-search","none of the above."],"a":0,"e":"Slide 30: time complexity = <b>number of nodes</b> generated/expanded, measured with b, d and m. The path cost measures solution quality, not time.","from":[{"s":"Q23-1B","qn":"Q1.7","pg":3}]},{"id":"Q23-1B-1-8","ch":3,"sl":"30, 33, 45","tp":"What defines a search strategy","t":"mcq","q":"A tree-search strategy is defined by the way to:","o":["the order of expanding the leaf nodes","arrange the leaf nodes in the memory (fringe) for exploration","both a + b","None of the above."],"a":2,"e":"Slide 30: a search strategy is defined by picking the <b>order of node expansion</b>; slides 33 and 45 show that this order is implemented by how the leaves are arranged in the fringe (FIFO, LIFO, priority queue). <b>Both</b>.","from":[{"s":"Q23-1B","qn":"Q1.8","pg":3}]},{"id":"F23-3-1A-5","ch":3,"sl":"38","tp":"When BFS is optimal","t":"mcq","q":"Breadth First Search is optimal","o":["when there are a few numbers of nodes.","when all step costs are equal.","when all step costs are unequal.","none of the mentioned."],"a":1,"e":"Slide 38: BFS is optimal <b>if costs are equal for all steps</b> — then the shallowest goal is also the cheapest.","from":[{"s":"F23-3","qn":"Q1 A.5","pg":1}]},{"id":"M22-1-2-1","ch":3,"sl":"9, 14–15","tp":"3-location vacuum world formulation","t":"short","q":"Consider a single-state agent architecture for a <b>3-location</b> vacuum cleaner.<br>a. Size of the state space.<br>b. Initial configuration and goal test.<br>c. Successor function.","a":"a. Agent location (3) × dirt configurations (2<sup>3</sup>) = 3 × 8 = <b>24 states</b>.<br>b. Initial state: any one of the 24 states. Goal test: <b>no dirt in any location</b>, wherever the agent is.<br>c. Actions Left, Right (change the agent's location) and Suck (removes the dirt in the current location); each costs 1.","e":"Slides 14–15 (vacuum world state space): states = dirt and robot location; actions Left, Right, Suck; goal test = no dirt at all locations; path cost 1 per action. With 2 locations there are 2 × 2<sup>2</sup> = 8 states; with 3 locations, 3 × 2<sup>3</sup> = 24. Slide 9 lists the parts of a well-defined problem.","from":[{"s":"M22-1","qn":"Q2 Q1","pg":3}]},{"id":"M22-1-2-2","ch":3,"sl":"33, 40, 45; ch4 12","tp":"Fringe ordering and data structure","t":"short","q":"The generic tree-search algorithm uses a data structure <i>Fringe</i> containing the leaf nodes waiting to be expanded. For each strategy (DFS, BFS, UCS, A*), give the node ordering in the fringe and the data structure that implements it.<br>Orderings: A. increasing f(n) = d (depth) · B. decreasing f(n) = d · C. increasing f(n) = g(n) + h(n) · D. increasing f(n) = g(n)<br>Structures: 1. Priority queue · 2. Queue (FIFO) · 3. Stack (LIFO)","a":"DFS → <b>B, 3</b> (deepest first, stack)<br>BFS → <b>A, 2</b> (shallowest first, FIFO queue)<br>UCS → <b>D, 1</b> (lowest g, priority queue)<br>A* → <b>C, 1</b> (lowest g + h, priority queue)","e":"Uninformed search slide 33: BFS fringe = FIFO queue; slide 45: DFS fringe = LIFO queue (stack), put successors at the front; slide 40: UCS = priority queue ordered by g. Informed search slide 12: A* orders by f = g + h.","from":[{"s":"M22-1","qn":"Q2 Q2","pg":3}]},{"id":"M21-1-1-2","ch":3,"sl":"10, 30","tp":"Optimal search algorithm","t":"mcq","q":"An optimal search algorithm","o":["finds the solution that has the lowest path cost among all solutions","finds all solutions","finds a solution using the least amount of memory","is guaranteed to find a solution when there is one"],"a":0,"e":"Slide 30: optimality — does it always find a <b>least-cost</b> solution? (Slide 10: the optimal solution has the lowest path cost.) Option D is completeness.","from":[{"s":"M21-1","qn":"Q1.2","pg":2}]},{"id":"M21-1-2","ch":3,"sl":"40–45, 57, 59; ch4 5, 12, 19","tp":"DFS, greedy, UCS, A* (graph search)","t":"short","q":"Consider the graph in the figure (A is the start, G the goal). Children are visited in alphabetical order when the algorithm gives no other order. Do <b>not</b> expand any node twice.<br>(a) For each strategy give the path solution and its cost:<br>• Depth-first search<br>• Greedy best-first search with h1 = {h(A) = 3, h(B) = 6, h(C) = 4, h(D) = 3}<br>• Uniform cost search<br>(b) Will A* find the optimal goal with H = {h(A) = 3, h(B) = 6, h(C) = 6, h(D) = 3}? Why?","img":"M21-1-2.jpg","a":"(a) <b>DFS</b>: A → B (alphabetical) → C (A already visited) → G: path <b>A-B-C-G</b>, cost 1 + 5 + 1 = <b>7</b>.<br><b>Greedy (h1)</b>: A → B(6), D(3); expand D → C(4), G(0); select G: path <b>A-D-G</b>, cost <b>6</b>.<br><b>UCS</b>: A(0) → B1, D3; B(1) → C6, D5, G7; D(3) → C4, G6; C(4) → G5; select G(5): path <b>A-D-C-G</b>, cost <b>5</b>.<br>(b) <b>No.</b> H is not admissible: h(C) = 6 &gt; h*(C) = 1 and h(D) = 3 &gt; h*(D) = 2. A* runs A → B 1+6 = 7, D 3+3 = 6 → D → C 4+6 = 10, G 6+0 = 6 → returns A-D-G with cost 6 instead of 5.","e":"Uninformed search slides 44–45 and 59: DFS with a closed list (graph search) never re-expands a node. Slide 40: UCS orders by g(n). Informed search slide 5: greedy uses h only; slides 12 and 19: A* uses g + h and is optimal only when h never overestimates.","from":[{"s":"M21-1","qn":"Q2","pg":4}]},{"id":"Q21-1MA-2","ch":3,"sl":"40–42, 59","tp":"UCS graph search: fringe order and tree","t":"short","q":"Given the graph in the figure, where S is the start and G the goal (numbers on arcs are step costs), trace <b>graph search</b> with UCS: show the order in which nodes are added to the fringe, the generated tree and the solution path. Do not add a state as a leaf if it is already on the path from the root. Nodes are added in alphabetical order. Is the solution optimal?<br><small>Arcs: S→A 1, S→G 12, A→B 3, A→C 1, B→D 3, C→D 1, C→G 2, D→G 3.</small>","img":"Q21-1MA-2.jpg","a":"Fringe (g in brackets): S(0) → A(1), G(12) → expand A: B(4), C(2) → expand C: D(3), G(4) → expand D: G(6) (worse than G(4)) → expand B: D(7) is already closed → select G(4).<br>Expanded: S, A, C, D, B · tree: S → {A, G}, A → {B, C}, C → {D, G}, D → {G}.<br>Solution <b>S-A-C-G</b>, cost <b>4</b> — <b>optimal</b> (UCS with positive step costs).","e":"Uninformed search slide 40: UCS stores the fringe as a priority queue on g(n). Slide 59: graph search keeps a closed list, so an already expanded state is not expanded again. Slide 42: UCS is optimal when all step costs are positive.","from":[{"s":"Q21-1","qn":"Q3 (p. 2)","pg":2},{"s":"Q21-1MA","qn":"Q2","pg":1}]},{"id":"Q21-1-2","ch":3,"sl":"31","tp":"Iterative deepening from a to f","t":"short","q":"Consider the undirected graph with edges a–b, a–c, a–d, b–c, b–e, b–f, c–f, d–g. Using <b>iterative deepening search (IDS)</b>, reach f from a. Nodes are visited in alphabetical order.","a":"Depth limit 0: a.<br>Depth limit 1: a, b, c, d (no goal).<br>Depth limit 2: a, b, e, <b>f</b> → goal found.<br>Expanded in the last iteration: a, b (then e and f are generated). Path <b>a-b-f</b>.","e":"Uninformed search slide 31 lists iterative deepening among the uninformed strategies: run depth-limited DFS with limit 0, 1, 2, … until a goal is found. It combines DFS's small memory (slide 57) with BFS's completeness (it finds the shallowest goal).","nb":"Your slides only list IDS by name (slide 31); the method is from the textbook. Graph drawn on a graded student copy.","from":[{"s":"Q21-1","qn":"Q2","pg":1}]},{"id":"Q26-1-2-1","ch":4,"sl":"12, 19; ch3 40–42, 59","tp":"UCS and A* graph search (h(C) inadmissible)","t":"short","q":"Consider the graph in the figure, where A is the start state and G the goal. Arcs are labelled with their cost and the heuristic to the goal is shown inside each node (A 3, B 6, C 3, D 1, E 5, G 0). Use <b>graph search</b> with UCS and with A*, and give: 1) the expanded nodes in order, 2) the path solution, 3) its cost, 4) whether this algorithm will always produce an optimal solution for this problem, and why. Children with the same cost go on the fringe in alphabetical order.<br><small>Edges: A–B 2, A–C 3, B–C 4, B–D 5, B–E 2, C–D 1, C–G 3, D–G 1, E–G 6.</small>","img":"Q26-1-2-1.jpg","a":"<b>UCS</b>: A(0) → B2, C3; B(2) → D7, E4; C(3) → D4, G6; D(4) → G5 (D and E tie at 4, D first); E(4) → G10; G(5) is selected.<br>Expanded <b>A, B, C, D, E</b> · path <b>A-C-D-G</b> · cost <b>5</b> · <b>always optimal</b> here: all step costs are positive and b is finite.<br><b>A*</b>: A (0+3) → B 2+6 = 8, C 3+3 = 6; C(6) → D 4+1 = 5, G 6+0 = 6; D(5) → G 5+0 = 5; G(5) is selected.<br>Expanded <b>A, C, D</b> · path <b>A-C-D-G</b> · cost <b>5</b>. It found the optimum this time, but it is <b>not guaranteed</b>: h is not admissible, since h(C) = 3 &gt; h*(C) = 2 (C-D-G).","e":"Uninformed search slides 40–42: UCS expands the lowest g(n) and is optimal with positive step costs; slide 59: graph search keeps a closed list and never expands a node twice. Informed search slide 12: A* orders by f = g + h; slide 19: the optimality guarantee needs h(n) ≤ h*(n) for every node.","from":[{"s":"Q26-1","qn":"Q2.1","pg":2}]},{"id":"Q26-1-2-2","ch":4,"sl":"2, 5, 19, 27","tp":"Jigsaw puzzle heuristic for greedy search","t":"short","q":"An AI agent is solving a <b>jigsaw puzzle</b> using Greedy Best-First Search. The puzzle consists of many pieces with different shapes, colours and patterns. At this stage, the agent must select one of the pieces A, B or C to fill location (1) in the partially completed puzzle (see the figure).<br>a) Design an admissible heuristic function that can help the agent determine which piece is most promising for the empty position.<br>b) Using your heuristic, rank pieces A, B and C from most promising to least promising and explain why.","img":"Q26-1-2-2.jpg","a":"a) One good choice: <b>h(piece) = number of the piece's sides that do not fit the neighbours of location (1)</b> — a side does not fit if its shape (tab / hole) does not lock with the neighbouring edge, or its colours/pattern along the border do not continue the picture. h = 0 means a perfect fit. It is admissible because every mismatching side is a real error that must be fixed, so h never counts more than the true number of corrections (it never overestimates), and it is 0 for the correct piece.<br>b) Compute h for each piece and sort by increasing h: the piece whose tabs and holes lock with the edges around (1) <i>and</i> whose colours continue the surrounding scene gets the smallest h and is placed first; a piece whose shape cannot even lock with the hole (h = 4 for all sides) is last. Greedy best-first then picks the piece with the lowest h.","e":"Slide 2: a heuristic h(n) estimates the remaining cost and must be 0 at a goal. Slide 5: greedy best-first expands the node with the lowest h. Slide 19: admissible = never overestimates. Slide 27: counting violated conditions of a relaxed problem (like misplaced tiles in the 8-puzzle) gives an admissible heuristic.","nb":"Open question, unanswered copy. The ranking in (b) depends on comparing the photo details carefully; the method above is what is graded.","from":[{"s":"Q26-1","qn":"Q2.2","pg":3}]},{"id":"M25-3-1-5","ch":4,"sl":"29","tp":"Least memory: hill climbing","t":"mcq","q":"Which of the following search strategies uses the least memory?","o":["BFS","UCS","A*","Hill Climbing"],"a":3,"e":"Informed search, slide 29: local search keeps only <b>one current state</b> and does not remember paths or reached states — its advantage is <i>using very little memory</i>. BFS and UCS keep the whole frontier (exponential space), and A* keeps all generated nodes (slide 20: O(b<sup>m</sup>) space).","from":[{"s":"M25-3","qn":"Q1.5","pg":1}]},{"id":"M25-3-1-6","ch":4,"sl":"12","tp":"A* evaluation function","t":"mcq","q":"What is the evaluation function used in A*?","o":["f(n) = g(n): total cost from the root to the current node","f(n) = h(n): estimated cost from the current node to a goal state","f(n) = min(g(n), h(n))","f(n) = g(n) + h(n)"],"a":3,"e":"Slide 12: A* uses <b>f(n) = g(n) + h(n)</b> — g(n) is the exact cost so far (as in UCS) and h(n) the estimated cost to the goal (as in greedy). f(n) = g(n) is UCS; f(n) = h(n) is greedy best-first.","from":[{"s":"M25-3","qn":"Q1.6","pg":1}]},{"id":"M25-3-1-7","ch":4,"sl":"28–43","tp":"Not a local search","t":"mcq","q":"Which of the following is not a local search technique?","o":["Hill Climbing","Local Beam Search","Greedy Best First Search","Genetic Algorithms"],"a":2,"e":"Slides 28–44 list the local search algorithms: hill climbing, local beam search and genetic algorithms — they keep complete configurations and ignore the path. <b>Greedy best-first search</b> (slide 5) is a best-first <i>path</i> search that keeps a fringe, so it is not local search.","from":[{"s":"M25-3","qn":"Q1.7","pg":1}]},{"id":"M24-3-1A-3","ch":4,"sl":"29","tp":"When hill climbing stops","t":"mcq","q":"When will the Hill-Climbing algorithm terminate?","o":["Stopping criterion met","Global Min/Max is achieved","No neighbor has better value","All of the mentioned"],"a":2,"e":"Slide 29: hill climbing moves to the best neighbor on each iteration <i>until reaching a peak where no neighbor has a higher value</i>. That peak may be only a local maximum (slide 35), so reaching the global optimum is not what stops it (model answer: c).","from":[{"s":"Q25-3","qn":"Q1.4","pg":1},{"s":"M24-3","qn":"Q1 A.3","pg":2}]},{"id":"Q25-3-1-5","ch":4,"sl":"11, 19–20","tp":"Complete and optimal with admissible h","t":"mcq","q":"Which search is complete and optimal when the heuristic function h(n) is admissible?","o":["Best-first search","Greedy Best-first search","Depth-first search","A* search"],"a":3,"e":"Slides 19–20: with an admissible h, <b>A*</b> is cost-optimal and complete. Greedy is not optimal (slide 11) and DFS is neither complete nor optimal (uninformed search slide 57).","from":[{"s":"Q25-3","qn":"Q1.5","pg":1},{"s":"Q24-1","qn":"Q1.3","pg":1}]},{"id":"Q25-3-1-6","ch":4,"sl":"29","tp":"Local search memory","t":"mcq","q":"Local Search Algorithms use","o":["Exponential memory space.","Polynomial memory space.","Linear memory space.","Constant memory space."],"a":3,"e":"Slide 29: local search keeps only the current state, not the paths or the reached states — <i>using very little memory</i>, a <b>constant</b> amount (k states for local beam search).","from":[{"s":"Q25-3","qn":"Q1.6","pg":1}]},{"id":"Q25-3-2-1","ch":4,"sl":"12, 19; ch3 32, 40","tp":"BFS, UCS, A* tree search (A to E)","t":"short","q":"Consider the search graph in the figure, where A is the start node and E the goal. Arcs are labelled with their cost and the heuristic to the goal is shown inside the nodes. Apply Breadth First Search, Uniform Cost Search and A* using <b>tree search</b>: give the expanded nodes in order, the path solution and its cost. Children with the same cost go on the fringe in alphabetical order. Repeated nodes are possible.<br><small>Edges: A–B 40, A–C 10, B–E 13, C–E 9, C–D 8, D–E 9 · h: A 18, B 10, C 7, D 8, E 0.</small>","img":"Q25-3-2.jpg","a":"<b>BFS</b> (FIFO, goal test when a node is selected): A → B, C; B → A, E; C → A, D, E; A → B, C; then E is selected. Expanded <b>A, B, C, A</b> · path <b>A-B-E</b> · cost 40 + 13 = <b>53</b>. (If you test the goal when it is generated, BFS stops while expanding B: same path.)<br><b>UCS</b>: A(0) → B40, C10; C(10) → A20, D18, E19; D(18) → C26, E27; E(19) selected. Expanded <b>A, C, D</b> · path <b>A-C-E</b> · cost <b>19</b>.<br><b>A*</b>: A (0+18) → B 40+10 = 50, C 10+7 = 17; C(17) → A 20+18 = 38, D 18+8 = 26, E 19+0 = 19; E(19) selected. Expanded <b>A, C</b> · path <b>A-C-E</b> · cost <b>19</b>.","e":"Uninformed search slide 32: BFS expands level by level (fewest edges, not cheapest). Slide 40: UCS expands the lowest g(n). Informed search slide 12: A* expands the lowest g + h; here h never overestimates (h(A) = 18 ≤ 19, h(B) = 10 ≤ 13, h(C) = 7 ≤ 9, h(D) = 8 ≤ 9), so A* is optimal (slide 19).","from":[{"s":"Q25-3","qn":"Q2.1","pg":2}]},{"id":"Q25-3-2-2","ch":4,"sl":"19","tp":"Admissible = underestimate","t":"tf","q":"An admissible heuristic is an underestimation of the true cost of the path from each state to a goal state.","a":0,"e":"Slide 19: admissible means h(n) ≤ h*(n) — it <b>never overestimates</b> (it is optimistic). (Strictly it may also be exactly equal.) <b>True</b>.","from":[{"s":"Q25-3","qn":"Q2.2","pg":2},{"s":"Q23-1B","qn":"Q1.5","pg":2}]},{"id":"F25-3-1-4","ch":4,"sl":"12","tp":"g(n) in A*","t":"mcq","q":"In the A* algorithm, what does g(n) represent?","o":["Actual cost from start to node n","Estimated cost from start to goal","Heuristic cost from node n to goal","Number of nodes expanded"],"a":0,"e":"Slide 12: g(n) = <b>exact cost so far to reach n</b>; h(n) = estimated cost from n to the goal; f(n) = g(n) + h(n) = estimated cost of the best path through n.","from":[{"s":"F25-3","qn":"Q1.4","pg":1}]},{"id":"F25-3-1-5","ch":4,"sl":"12; ch3 40","tp":"A* with h = 0 is UCS","t":"mcq","q":"If the heuristic function h(n) = 0 for all nodes, A* reduces to which search algorithm?","o":["Breadth-First Search","Depth-First Search","Uniform Cost Search","Greedy Best-First Search"],"a":2,"e":"Slide 12: A* combines UCS (g) and greedy (h). With h = 0, f(n) = g(n) — exactly UCS's ordering (uninformed search slide 40).","from":[{"s":"F25-3","qn":"Q1.5","pg":1}]},{"id":"F25-3-1-6","ch":4,"sl":"38","tp":"k in local beam search","t":"mcq","q":"In local beam search, what is 'k'?","o":["Number of children per node","Number of goals","Number of neighbors explored","Number of states kept in memory at each iteration"],"a":3,"e":"Slide 38: local beam search keeps track of <b>k states</b> rather than one; at each iteration it selects the k best successors from all of them (slide 39: k is the beam width).","from":[{"s":"F25-3","qn":"Q1.6","pg":1}]},{"id":"M25-2-1-3","ch":4,"sl":"4, 12","tp":"Priority queue: A*","t":"mcq","q":"Which algorithm uses a priority queue to keep track of nodes to be explored?","o":["Breadth-First Search","Depth-First Search","Hill Climbing","A* Search"],"a":3,"e":"Informed search, slide 4: best-first search orders the nodes in the fringe by the evaluation function f(n); A* (slide 12) is best-first with f(n) = g(n) + h(n), so its fringe is a <b>priority queue</b>. BFS uses a FIFO queue and DFS a LIFO stack (uninformed search, slides 33, 45); hill climbing keeps only the current state (slide 29).","from":[{"s":"M25-2","qn":"Q1.3","pg":4}]},{"id":"M25-2-2A-1","ch":4,"sl":"28","tp":"Bin packing: state representation","t":"mcq","q":"<i>Bin packing:</i> you have a set of items, each with a specific weight, and a set of bins, each with a fixed capacity. The goal is to pack all items into the minimum number of bins.<br>Which of the following BEST describes a direct representation of a bin packing solution suitable for local search?","o":["A list of items sorted by weight.","A list of bins, where each bin contains a list of the items packed into it.","A list of bin capacities.","A single integer representing the total number of bins used."],"a":1,"e":"Slide 28: in local search the state space is a set of <b>complete configurations</b> and the goal state itself is the solution. A complete bin-packing configuration says which items are in which bin — a list of bins with their items. The other options do not describe an assignment of items to bins.","from":[{"s":"M25-2","qn":"Q2 A.1","pg":1}]},{"id":"M25-2-2A-2","ch":4,"sl":"29–30","tp":"Bin packing: neighborhood","t":"mcq","q":"<i>Bin packing</i> (same problem). Which of the following BEST describes a suitable neighborhood definition for a local search algorithm applied to the bin packing problem?","o":["Moving a single item from one bin to another.","Removing a single item from a particular bin.","Swapping all items between two different bins.","All of the above."],"a":0,"e":"Slides 29–30: local search moves from the current state to a <b>neighboring state</b> — a small change that gives another complete configuration. Moving one item to another bin does exactly that. Removing an item leaves it unpacked (not a complete solution), and swapping the whole contents of two bins just relabels the bins (same packing, same value).","from":[{"s":"M25-2","qn":"Q2 A.2","pg":1}]},{"id":"M25-2-2A-3","ch":4,"sl":"28","tp":"Bin packing: feasible solution","t":"mcq","q":"<i>Bin packing</i> (same problem). What constitutes a <i>feasible</i> solution to the bin packing problem?","o":["A solution that uses the minimum possible number of bins.","A solution where all items are packed into bins, and the total weight of items in each bin does not exceed the bin's capacity.","A solution where all bins are completely full.","A solution with no empty bins."],"a":1,"e":"A feasible solution is a configuration that <b>satisfies the constraints</b> (slide 28: finding a valid configuration satisfying constraints): every item is packed and no bin is over capacity. Using the minimum number of bins is what makes a solution <i>optimal</i>, which is a stronger condition.","from":[{"s":"M25-2","qn":"Q2 A.3","pg":1}]},{"id":"M25-2-2A-4","ch":4,"sl":"29, 35–36","tp":"No improving move = local optimum","t":"mcq","q":"What does it mean for a local search algorithm to stop because \"no improving moves can be found in the neighborhood\"?","o":["The algorithm has found the global optimum.","The algorithm has explored the entire search space.","The current solution is better than all of its immediate neighbors (i.e. a local optimum state).","The algorithm has found a feasible solution."],"a":2,"e":"Slide 29: hill climbing moves to the best neighbor until it reaches a peak where no neighbor has a higher value. Slides 35–36: depending on the initial state it can get stuck in a <b>local maximum / minimum</b> (e.g. the 8-queens state with h = 1 where every successor is worse). So stopping only tells you the state beats its neighbors, not that it is the global optimum.","from":[{"s":"M25-2","qn":"Q2 A.4","pg":1}]},{"id":"F24-1-2-1","ch":4,"sl":"19, 26","tp":"max of admissible heuristics","t":"tf","q":"h1 and h2 are two admissible heuristics; h3 = max{h1, h2} is an admissible heuristic.","a":0,"e":"Slide 19: admissible = h(n) ≤ h*(n) for every n. If h1 ≤ h* and h2 ≤ h*, then max(h1, h2) ≤ h* too. (And it dominates both, slide 26.) <b>True</b>.","from":[{"s":"Q25-2","qn":"Q2.2","pg":1},{"s":"F24-1","qn":"Q2.1","pg":5}]},{"id":"Q25-2-1-4","ch":4,"sl":"11, 19–20","tp":"Why A* beats greedy","t":"mcq","q":"A* with an admissible heuristic is preferred over greedy best-first search because of the following:","o":["Time complexity.","Space complexity.","Time complexity and optimality.","Completeness and optimality."],"a":3,"e":"Slides 11 and 20: greedy and A* have the same worst-case time and space, O(b<sup>m</sup>). But greedy is not optimal and can loop, while A* with an admissible h is <b>complete and optimal</b> (slides 19–20).","from":[{"s":"Q25-2","qn":"Q1.4","pg":2}]},{"id":"Q25-2-1-5","ch":4,"sl":"29, 35","tp":"False statement about local search","t":"mcq","q":"Which of the following statements about local search algorithms is <b>not</b> correct?","o":["They explore the search space by making small changes to a current solution.","They typically have lower memory requirements.","They are guaranteed to find the optimal solution to a problem.","They can be susceptible to getting stuck in local optima."],"a":2,"e":"Slide 29: local search moves to neighbouring states and uses very little memory, finding good <i>sub-optimal</i> solutions. Slide 35: it can get stuck in local maxima. So it is <b>not guaranteed to find the optimal solution</b>.","from":[{"s":"Q25-2","qn":"Q1.5","pg":2}]},{"id":"Q25-2-2-1","ch":4,"sl":"12; ch3 40, 45","tp":"DFS, UCS, A* tree search (A to G)","t":"short","q":"Consider the search graph in the figure, where A is the start node and G the goal. Arcs are labelled with their cost; the heuristic is inside each node. Apply Depth First Search, Uniform Cost Search and A* using <b>tree search</b>: give the expanded nodes in order, the path solution and its cost. Children with the same cost go on the fringe in alphabetical order. Repeated nodes are possible.<br><small>Directed edges: A→B 1, A→C 5, B→C 1, B→D 9, C→D 2, D→E 8, D→G 4, E→G 3 · h: A 7, B 7, C 2, D 2, E 2, G 0.</small>","img":"Q25-2-2.jpg","a":"<b>DFS</b>: always the first child alphabetically: A → B → C → D → E → G. Expanded <b>A, B, C, D, E</b> · path <b>A-B-C-D-E-G</b> · cost 1+1+2+8+3 = <b>15</b>.<br><b>UCS</b>: A(0) → B1, C5; B(1) → C2, D10; C(2) → D4; D(4) → E12, G8; C(5) → D7; D(7) → E15, G11; G(8) selected. Expanded <b>A, B, C, D, C, D</b> · path <b>A-B-C-D-G</b> · cost <b>8</b>.<br><b>A*</b>: A (0+7) → B 1+7 = 8, C 5+2 = 7; C(7) → D 7+2 = 9; B(8) → C 2+2 = 4, D 10+2 = 12; C(4) → D 4+2 = 6; D(6) → E 12+2 = 14, G 8+0 = 8; G(8) selected. Expanded <b>A, C, B, C, D</b> · path <b>A-B-C-D-G</b> · cost <b>8</b>.","e":"Uninformed search slide 45: DFS (LIFO) goes deepest first and ignores cost. Slide 40: UCS expands the lowest g(n). Informed search slide 12: A* expands the lowest f = g + h. In tree search the same state (C, D) can appear several times with different costs.","from":[{"s":"Q25-2","qn":"Q2.1","pg":1}]},{"id":"Q25-2-2-3","ch":4,"sl":"19","tp":"Admissible never overestimates","t":"tf","q":"An admissible heuristic function in A* search always overestimates the cost to reach the goal.","a":1,"e":"Slide 19: an admissible heuristic <b>never</b> overestimates the cost to reach the goal (h(n) ≤ h*(n)). <b>False</b>.","from":[{"s":"Q25-2","qn":"Q2.3","pg":1}]},{"id":"F25-2-B","ch":4,"sl":"12, 30; ch3 32; ch5 18; ch6 77","tp":"Match algorithm to characteristic","t":"short","q":"Match each algorithm/technique with its MOST distinctive characteristic:<br>1. Breadth-First Search &nbsp; 2. Hill Climbing &nbsp; 3. A* Search &nbsp; 4. Forward Checking (for CSPs) &nbsp; 5. Minimax Search<br>A. Uses a heuristic function and path cost to find the optimal solution.<br>B. Used in adversarial search.<br>C. Removes inconsistent values from the domains of unassigned variables.<br>D. Explores all nodes at the current depth before moving to the next.<br>E. Moves to the neighbor with the best heuristic value, may get stuck in local optima.","a":"1 → <b>D</b> &nbsp; 2 → <b>E</b> &nbsp; 3 → <b>A</b> &nbsp; 4 → <b>C</b> &nbsp; 5 → <b>B</b>","e":"BFS expands all nodes at depth i before depth i + 1 (uninformed search slide 32). Hill climbing moves to the best neighbour and can get stuck in local maxima (informed search slides 30, 35). A* uses f = g + h and is optimal with an admissible h (slides 12, 19). Forward checking deletes inconsistent values from unassigned neighbours (CSP slide 77). Minimax is the adversarial-search algorithm (games slides 18–24).","nb":"The student copy in the merged final file swaps 4 and 5 — that is a student mistake.","from":[{"s":"F25-2","qn":"Q1 B","pg":3}]},{"id":"F25-2-TF2","ch":4,"sl":"4–5","tp":"Greedy fringe order","t":"tf","q":"In Greedy Best-First search, the nodes are arranged in the fringe according to an increasing order of the cost f = h.","a":0,"e":"Slides 4–5: best-first search orders the fringe by f(n), most desirable first; greedy uses f(n) = h(n), so the node with the smallest h comes first. <b>True</b>.","from":[{"s":"F25-2","qn":"Q2.2","pg":3}]},{"id":"F25-2-M2","ch":4,"sl":"43–44","tp":"Single-point crossover","t":"mcq","q":"In a Genetic Algorithm, consider two parent chromosomes represented as binary strings: Parent 1: 11001010 and Parent 2: 10101100. Applying a single-point crossover at the fourth position, the resulting offspring chromosome 1 will be:","o":["11001100","10101011","10101100","11001010"],"a":0,"e":"Slides 43–44: a successor is made by combining two parents — crossover takes the first part from one parent and the rest from the other. Cut after position 4: Parent 1 gives <b>1100</b>, Parent 2 gives the tail <b>1100</b> → offspring 1 = <b>11001100</b> (offspring 2 would be 1010 + 1010).","from":[{"s":"F25-2","qn":"MCQ 2","pg":7}]},{"id":"M25-1-1-6","ch":4,"sl":"2","tp":"Why heuristic search","t":"mcq","q":"<b>Heuristic search</b> uses additional knowledge about the problem in order to:","o":["Reduce memory requirements","Make the search complete","Guide the search toward more promising paths","Remove the need for a goal state"],"a":2,"e":"Informed search, slide 2: heuristic (informed) search exploits additional knowledge about the problem that helps to <b>guide search to more promising paths</b>, so it can find solutions more efficiently than uninformed search.","from":[{"s":"M25-1","qn":"Q1.6","pg":2}]},{"id":"M25-1-1-7","ch":4,"sl":"19","tp":"Admissible heuristic","t":"mcq","q":"A heuristic is <b>admissible</b> if:","o":["It always overestimates the real cost","It never overestimates the true cost to reach the goal","It is faster than A*","It reduces branching factor to 1"],"a":1,"e":"Slide 19: h(n) is admissible if h(n) ≤ h*(n) for every node — it <b>never overestimates</b> the cost to reach the goal (it is optimistic). With an admissible h, A* is cost-optimal.","from":[{"s":"M25-1","qn":"Q1.7","pg":2}]},{"id":"M25-1-2","ch":4,"sl":"12, 22–25","tp":"A* on the 8-puzzle (Manhattan distance)","t":"short","q":"Given the initial state of an 8-puzzle and the goal state in the figure. Using the <b>A*</b> algorithm, where g(n) = depth of the node and h(n) = Manhattan distance, complete all the empty states and calculate the evaluation function f(n) for each state.<br>Initial: 1 2 3 / _ 4 6 / 7 5 8 &nbsp;·&nbsp; Goal: 1 2 3 / 4 5 6 / 7 8 _","img":"M25-1-2.jpg","a":"Initial (g = 0): h = 3 (tiles 4, 5, 8 are each 1 square away) → f = 3.<br><b>Depth 1</b> (blank moves up / right / down):<br>• _ 2 3 / 1 4 6 / 7 5 8 → g = 1, h = 4 (1, 4, 5, 8), <b>f = 5</b><br>• 1 2 3 / 4 _ 6 / 7 5 8 → g = 1, h = 2 (5, 8), <b>f = 3</b> ← expanded next<br>• 1 2 3 / 7 4 6 / _ 5 8 → g = 1, h = 4 (7, 4, 5, 8), <b>f = 5</b><br><b>Depth 2</b> (children of 1 2 3 / 4 _ 6 / 7 5 8, without going back):<br>• 1 _ 3 / 4 2 6 / 7 5 8 → g = 2, h = 3 (2, 5, 8), <b>f = 5</b><br>• 1 2 3 / 4 5 6 / 7 _ 8 → g = 2, h = 1 (8), <b>f = 3</b> ← expanded next<br>• 1 2 3 / 4 6 _ / 7 5 8 → g = 2, h = 3 (6, 5, 8), <b>f = 5</b><br><b>Depth 3</b> (children of 1 2 3 / 4 5 6 / 7 _ 8):<br>• 1 2 3 / 4 5 6 / _ 7 8 → g = 3, h = 2 (7, 8), <b>f = 5</b><br>• 1 2 3 / 4 5 6 / 7 8 _ (goal) → g = 3, h = 0, <b>f = 3</b><br>A* always expands the lowest f, so the solution is right, down, right with cost 3.","e":"Slide 12: A* expands the node with the lowest f(n) = g(n) + h(n). Slides 22–25: h2 = total Manhattan distance = sum over tiles (not the blank) of the number of squares each tile is from its goal square. In the figure the left/right boxes of each level are the other two moves (their order on the page does not matter).","from":[{"s":"M25-1","qn":"Q2","pg":3}]},{"id":"F22-1-1-1","ch":4,"sl":"19–20","tp":"Which search is optimal","t":"mcq","q":"Which of the following search algorithms are optimal?","o":["Greedy best-first search","Depth first search","A* using admissible heuristic","Local search"],"a":2,"e":"Informed search slide 19: with an admissible heuristic, <b>A* is cost-optimal</b>. Greedy is not optimal (slide 11), DFS is not optimal (uninformed search, slide 57), and local search can stop at a local optimum (slide 35).","from":[{"s":"F25-1","qn":"Q1.3","pg":1},{"s":"F22-1","qn":"Q1.1","pg":2}]},{"id":"M24-3-1A-1","ch":4,"sl":"2","tp":"Search that uses problem-specific knowledge","t":"mcq","q":"The search strategy that uses problem-specific knowledge is known as ___________","o":["Informed Search","Best First Search","Heuristic Search","All of the mentioned"],"a":3,"e":"Informed search, slide 2: <i>heuristic or informed search</i> exploits additional knowledge about the problem; best-first search (slides 3–4) is the family of informed strategies driven by such an evaluation function. All three names refer to it — <b>all of the mentioned</b> (model answer: d).","from":[{"s":"M24-3","qn":"Q1 A.1","pg":2}]},{"id":"M24-3-1A-2","ch":4,"sl":"5","tp":"Greedy evaluation function","t":"mcq","q":"What is the evaluation function in the greedy approach?","o":["Heuristic function","Path cost from start node to current node","Path cost from start node to current node plus heuristic function","Average of path cost from start node to current node and heuristic function"],"a":0,"e":"Slide 5: greedy best-first search uses <b>f(n) = h(n)</b>, the heuristic estimate to the goal. g(n) alone is UCS; g(n) + h(n) is A* (slide 12).","from":[{"s":"M24-3","qn":"Q1 A.2","pg":2}]},{"id":"M24-3-1A-4","ch":4,"sl":"5","tp":"Expands the node closest to the goal","t":"mcq","q":"Which search method will expand the node that seems closest to the goal?","o":["Breadth first-search","Greedy best-first search","A* search","Depth first-search"],"a":1,"e":"Slide 5: <b>greedy best-first search</b> expands the node that <i>appears to be closest to the goal</i>, using only h(n).","from":[{"s":"M24-3","qn":"Q1 A.4","pg":2}]},{"id":"M24-3-1A-5","ch":4,"sl":"19–20","tp":"Complete and optimal with admissible h","t":"mcq","q":"Which search is complete and optimal when h(n) is admissible?","o":["Greedy best-first search","Depth-first search","A* using tree-search","Breadth first-search"],"a":2,"e":"Slide 19: if h(n) is admissible, A* is cost-optimal; slide 20: A* is complete (finite branching factor, positive step costs). Greedy is not optimal (slide 11), DFS is neither (uninformed search slide 57), and BFS ignores h.","from":[{"s":"M24-3","qn":"Q1 A.5","pg":2}]},{"id":"Q24-3-1-4","ch":4,"sl":"19","tp":"Admissible heuristics: all true","t":"mcq","q":"Admissible heuristics:","o":["are used in optimal A*","are less than the true costs","never overestimate the cost to reach the goal","all the above answers are correct"],"a":3,"e":"Slide 19: admissible means h(n) ≤ h*(n) — it never overestimates (it is optimistic, ≤ the true cost), and with an admissible h A* is cost-optimal. <b>All the above</b>.","from":[{"s":"Q24-3","qn":"Q1.4","pg":1}]},{"id":"Q24-3-1-5","ch":4,"sl":"29, 38","tp":"Beam search with k = 1","t":"mcq","q":"Local beam search with (k = 1) is called:","o":["Hill climbing search","Breadth first search","Best first search","A* search"],"a":0,"e":"Slide 38: local beam search keeps the k best states at each step. With k = 1 it keeps only the single best successor — exactly <b>hill climbing</b> (slide 29: one current state, move to the best neighbour).","from":[{"s":"Q24-3","qn":"Q1.5","pg":1},{"s":"Q22-1","qn":"Q1.10","pg":3}]},{"id":"Q24-3-2","ch":4,"sl":"12, 19; ch3 40","tp":"UCS and A* with two goals","t":"short","q":"Consider the directed graph in the figure, where S is the start node and G1 and G2 are two goal states. Arcs are labelled with their cost; the heuristic is shown inside the nodes.<br>1. Apply UCS and A* (tree search) and give the goal reached, the expanded nodes in order, the path solution and its cost (alphabetical order for ties).<br>2. Is each obtained solution optimal? Justify.","img":"Q24-3-2.jpg","a":"1. <b>UCS</b>: expanded S(0), B(6), A(7), C(8), D(9), E(9), D(10), C(13), E(14), then G2(14) is selected. Goal <b>G2</b> · path <b>S-B-E-G2</b> · cost 6 + 3 + 5 = <b>14</b>.<br><b>A*</b>: S(12) → A 7+9 = 16, B 6+7 = 13, C 8+9 = 17; B(13) → C 13+9 = 22, D 10+8 = 18, E 9+10 = 19; A(16) → D 9+8 = 17; C(17) → E 14+10 = 24, F 16+3 = 19; D(17) → G1 18+0 = 18; D(18) → G1 19; G1(18) selected. Expanded <b>S, B, A, C, D, D</b> · goal <b>G1</b> · path <b>S-A-D-G1</b> · cost 7 + 2 + 9 = <b>18</b>.<br>2. UCS: <b>optimal</b> (positive costs). A*: <b>not optimal</b> (18 &gt; 14) because h is not admissible: h(E) = 10 &gt; 5, the real cost E → G2.","e":"Uninformed search slides 40–42: UCS expands the lowest g and is optimal with positive costs. Informed search slide 12: A* expands the lowest g + h; slide 19: it is guaranteed optimal only with an admissible h. Here the overestimate at E keeps the cheap path S-B-E-G2 (f = 19) behind G1 (f = 18).","from":[{"s":"Q24-3","qn":"Q2","pg":2}]},{"id":"M24-1-1-4","ch":4,"sl":"2","tp":"Key feature of informed search","t":"mcq","q":"Which of the following best describes the key feature of informed search algorithms?","o":["They explore all possible nodes","They use a heuristic to guide the search","They avoid revisiting nodes","They guarantee an optimal solution"],"a":1,"e":"Informed search, slide 2: informed search uses additional knowledge — a <b>heuristic h(n)</b> — to guide the search to more promising paths. Not all informed algorithms are optimal (greedy is not, slide 11), and avoiding revisits is graph search (uninformed search, slide 59).","from":[{"s":"M24-1","qn":"Q1.4","pg":1}]},{"id":"M24-1-1-5","ch":4,"sl":"2, 4–5","tp":"What a heuristic function is","t":"mcq","q":"What is a heuristic function?","o":["a function that provides an estimate of the cost of the path from a given node n to the closest goal state","a function that maps from problem state descriptions to measures of desirability","a function that measures how far a node in a search tree seems to be from a goal","all of the mentioned"],"a":3,"e":"Slide 2: h(n) estimates the cost of the cheapest path from node n to a goal (option A). Slide 4: the evaluation function is an estimate of <i>desirability</i> of a state (option B). Slide 5: greedy expands the node that <i>appears</i> closest to the goal according to h (option C). All three describe it — <b>all of the mentioned</b>.","from":[{"s":"M24-1","qn":"Q1.5","pg":2}]},{"id":"M24-1-1-7","ch":4,"sl":"19","tp":"Tree-search A* needs an admissible h","t":"mcq","q":"Which of the following statements about the Tree-search A* algorithm is true?","o":["A* search always finds the shortest path, regardless of the heuristic","A* will expand fewer nodes with a consistent heuristic than with an admissible heuristic","A* can only find an optimal solution if the heuristic is admissible","A* requires a search graph to function properly"],"a":2,"e":"Slide 19: the optimality guarantee of A* is tied to admissibility — <i>if h(n) is admissible, A* is cost-optimal</i>. With an overestimating h it can return a non-optimal path, so A is wrong; the question is about tree search, so D is wrong.","from":[{"s":"M24-1","qn":"Q1.7","pg":2}]},{"id":"M24-1-1-8","ch":4,"sl":"43","tp":"New states in a genetic algorithm","t":"mcq","q":"How are the new states generated in a genetic algorithm?","o":["Selection","Mutation","Crossover","All of the above"],"a":3,"e":"Slide 43: a successor state is generated by combining two parent states; the next generation is produced by <b>selection, crossover, and mutation</b> — all of the above.","from":[{"s":"M24-1","qn":"Q1.8","pg":2}]},{"id":"Q24-1-1-4","ch":4,"sl":"28","tp":"Path irrelevant → local search","t":"mcq","q":"In many problems the path to the goal is irrelevant. This class of problems can be answered using which of the following techniques?","o":["Informed Search","Uninformed Search","Local Search","None of these"],"a":2,"e":"Slide 28: <i>in many optimization problems the path to the goal is irrelevant; the goal state itself is the solution… in such cases we can use <b>local search</b> algorithms</i>.","from":[{"s":"Q24-1","qn":"Q1.4","pg":1}]},{"id":"Q24-1-1-5","ch":4,"sl":"29","tp":"Stops at a peak: hill climbing","t":"mcq","q":"The algorithm terminates when it reaches a peak where no neighbor has a higher value. Choose the correct algorithm:","o":["Local Beam Search","Hill-climbing search","Genetic Algorithm","All of the mentioned"],"a":1,"e":"Slide 29: the <b>hill climbing</b> process moves to the neighbouring state with the highest value until reaching a \"peak\" where no neighbour has a higher value.","from":[{"s":"Q24-1","qn":"Q1.5","pg":1}]},{"id":"Q24-1-2","ch":4,"sl":"12, 19; ch3 32","tp":"BFS and A*; is h1 / h2 admissible?","t":"short","q":"Consider the search graph in the figure, where S is the start node and G the goal. Arcs are labelled with their cost. The table gives two heuristic functions h1 and h2:<div class=\"tbl\"><table class=\"mini\"><tr><th>Node</th><th>S</th><th>B</th><th>C</th><th>D</th><th>E</th><th>F</th><th>G</th></tr><tr><td>h1</td><td>9</td><td>7</td><td>10</td><td>7</td><td>1</td><td>1</td><td>0</td></tr><tr><td>h2</td><td>12</td><td>10</td><td>16</td><td>9</td><td>3</td><td>4</td><td>0</td></tr></table></div>1. Apply Breadth First Search and A* (with h1) using <b>tree search</b>: give the expanded nodes in order, the path solution and its cost (alphabetical order for ties; repeated nodes are possible).<br>2. Is h1 admissible? Justify.<br>3. Is h2 admissible? Justify.","img":"Q24-1-2.jpg","a":"1. <b>BFS</b>: S → B, C, D; B → E; C → G; D → (nothing new); E → F, G; the first G in the queue is the one from C. Expanded <b>S, B, C, D, E</b> · path <b>S-C-G</b> · cost 1 + 15 = <b>16</b>.<br><b>A* (h1)</b>: S (0+9) → B 2+7 = 9, C 1+10 = 11, D 10+7 = 17; B(9) → E 9+1 = 10; E(10) → F 10+1 = 11, G 11+0 = 11; then C(11) and F(11) (alphabetical before G) are expanded; G(11) is selected. Expanded <b>S, B, E, C, F</b> · path <b>S-B-E-G</b> · cost <b>11</b>.<br>2. <b>Yes.</b> True costs to G: S 11, B 9, C 12, D 21, E 2, F 3. Every h1 value is ≤ these (9, 7, 10, 7, 1, 1).<br>3. <b>No.</b> h2 overestimates at B (10 &gt; 9), C (16 &gt; 12), E (3 &gt; 2) and F (4 &gt; 3).","e":"Uninformed search slide 32: BFS expands level by level, regardless of cost. Informed search slide 12: A* expands the lowest f = g + h. Slide 19: h is admissible iff h(n) ≤ h*(n) for every node — one overestimate is enough to break it.","nb":"The model answer uses C → G (15) as C's true cost; via S-B-E-G it is 12. h2(C) = 16 overestimates either way.","from":[{"s":"Q24-1","qn":"Q2","pg":2}]},{"id":"F24-1-1A-1","ch":4,"sl":"38","tp":"Keeps k states: local beam","t":"mcq","q":"_________ algorithm keeps track of k states rather than just one.","o":["Hill-climbing search","Local beam search","Breadth-first search","Genetic search"],"a":1,"e":"Slide 38: <b>local beam search</b> keeps track of k states rather than just one, starting with k randomly generated states. Hill climbing keeps a single current state (slide 29).","from":[{"s":"F24-1","qn":"Q1 A.1","pg":2}]},{"id":"F24-1-2-2","ch":4,"sl":"12; ch3 40","tp":"A* behaving like BFS","t":"tf","q":"A* search can be made to perform a Breadth-First Search by setting, for all nodes n, h(n) = 0, and for all edges, edge cost = 1.","a":0,"e":"With h = 0, f = g, so A* becomes UCS (informed search slide 12). With every edge cost 1, g(n) = depth, and UCS is equivalent to BFS when all step costs are equal (uninformed search slide 40). <b>True</b>.","from":[{"s":"F24-1","qn":"Q2.2","pg":5}]},{"id":"F24-1-2-5","ch":4,"sl":"4, 12","tp":"A* fringe order","t":"tf","q":"In the A* strategy, the nodes are arranged in the fringe according to increasing order of the cost f = g + h.","a":0,"e":"Slides 4 and 12: best-first expands the most desirable node first; for A*, the node with the lowest f(n) = g(n) + h(n). <b>True</b>.","from":[{"s":"F24-1","qn":"Q2.5","pg":5}]},{"id":"M23-1-1A-2","ch":4,"sl":"43","tp":"Next generation in a GA","t":"mcq","q":"In a genetic algorithm, the next generation of states is produced by:","o":["selection","crossover","mutation","All the above answers are correct."],"a":3,"e":"Slide 43: <i>produce the next generation of states by selection, crossover, and mutation</i>.","from":[{"s":"M23-1","qn":"Q1 A.2","pg":2}]},{"id":"M23-1-1A-5","ch":4,"sl":"2","tp":"Heuristic function definition","t":"mcq","q":"Heuristic function h(n) is ________","o":["Lowest path cost","Cheapest path from root to goal node","Estimated cost of cheapest path from the node n to goal node","Average path cost"],"a":2,"e":"Informed search, slide 2: h(n) provides an <b>estimate of the cost of the cheapest path from node n to a goal state</b>.","from":[{"s":"M23-1","qn":"Q1 A.5","pg":2},{"s":"M21-1","qn":"Q1.3","pg":2}]},{"id":"M23-1-2","ch":4,"sl":"5, 12, 19, 38–42; ch3 40–45, 57","tp":"UCS, DFS, greedy, A*, beam (k=2)","t":"short","q":"Consider the search space in the figure, where A is the start node and G satisfies the goal test. Arcs are labelled with their cost and the heuristic values are:<div class=\"tbl\"><table class=\"mini\"><tr><th>n</th><th>A</th><th>B</th><th>C</th><th>D</th><th>G</th></tr><tr><td>h(n)</td><td>3</td><td>6</td><td>4</td><td>3</td><td>0</td></tr></table></div>1. Apply uniform cost search, depth first search, greedy best first search, A* and beam search (k = 2): give the expanded nodes, the path from start to goal and its cost, if any. Children with the same cost go on the fringe in alphabetical order. Repeated nodes are possible.<br>2. For each strategy, is the obtained solution optimal? Justify.","img":"M23-1-2.jpg","a":"1. <b>UCS</b>: A(0) → B1, D3; B(1) → A3, C6, D5, G7; A(3) → B4, D6; D(3) → C4, G6; B(4) → …; C(4) → G5; D(5) …; G(5) selected. Expanded <b>A, B, A, D, B, C, D</b> → path <b>A-D-C-G</b>, cost <b>5</b>.<br><b>DFS</b>: A → B (alphabetical first) → A → B → … loops forever between A and B → <b>no solution</b>.<br><b>Greedy</b>: A → B(6), D(3); expand D → C(4), G(0); select G. Expanded <b>A, D</b> → path <b>A-D-G</b>, cost <b>6</b>.<br><b>A*</b>: A → B 1+6 = 7, D 3+3 = 6; expand D → C 4+4 = 8, G 6+0 = 6; select G (6). Expanded <b>A, D</b> → path <b>A-D-G</b>, cost <b>6</b>.<br><b>Beam (k = 2)</b>: level 1 keeps B and D; expanding them (B first) reaches G from B. Expanded <b>A, B, D</b> → path <b>A-B-G</b>, cost <b>7</b> (model answer).<br>2. • UCS: <b>optimal</b> — all step costs positive and b finite.<br>• DFS: <b>no</b> — it fails in spaces with loops and ignores costs.<br>• Greedy: <b>no</b> — follows h only (6 &gt; 5).<br>• A*: <b>no</b> here — h is not admissible: h(D) = 3 &gt; h*(D) = 2 (D-C-G) and h(C) = 4 &gt; h*(C) = 1.<br>• Beam: <b>no</b> — it keeps only k nodes chosen by h and can drop the optimal path (7 &gt; 5).","e":"Uninformed search slides 40–42: UCS expands the lowest g(n) and is optimal with positive costs. Slides 45 and 57: DFS (LIFO) is not complete in spaces with loops and not optimal. Informed search slide 5: greedy uses h only; slide 12: A* uses g + h; slide 19: A* is optimal only if h never overestimates. Slides 38–42: beam search keeps only the k best nodes at each level, so it may eliminate solutions.","nb":"The model answer justifies A* with h(B) > g(B); the nodes that actually break admissibility are C and D.","from":[{"s":"M23-1","qn":"Q2","pg":4},{"s":"M23-1","qn":"Q2 (cont.)","pg":5},{"s":"M23-1","qn":"Q2.2","pg":6}]},{"id":"F23-1-1-1","ch":4,"sl":"2","tp":"Knowledge beyond the problem definition","t":"mcq","q":"Which search uses problem-specific knowledge beyond the definition of the problem?","o":["Informed search","Depth-first search","Breadth-first search","Uninformed search"],"a":0,"e":"Informed search, slide 2: heuristic or <b>informed search</b> exploits additional knowledge about the problem to guide the search. DFS and BFS are uninformed (blind) strategies (uninformed search, slide 31).","from":[{"s":"F23-1","qn":"Q1.1","pg":1}]},{"id":"F23-1-1-8","ch":4,"sl":"29–30","tp":"Main step of hill climbing","t":"mcq","q":"What is the main step of the Hill climbing algorithm?","o":["Finding a neighboring solution that improves the current solution","Randomly selecting a solution from a pool of alternatives","Exploring all possible solutions exhaustively","Backtracking to previously visited solutions for optimization"],"a":0,"e":"Slides 29–30: on each iteration hill climbing moves to the <b>neighbouring state with a better value</b> (the current node is replaced by the best neighbour). It never backtracks and does not explore exhaustively.","from":[{"s":"F23-1","qn":"Q1.8","pg":1}]},{"id":"M23-3-1-3","ch":4,"sl":"19, 22–25","tp":"Which 8-puzzle heuristic is not admissible","t":"mcq","q":"In the n-puzzle problem, which of the following heuristics is <b>not</b> admissible?","o":["h = 0","h = the number of correctly placed tiles","h = the sum of the straight-line distances from each tile to its goal","All the above heuristics are admissible."],"a":1,"e":"Slide 19: admissible means h(n) ≤ true cost for every node (and h = 0 at the goal, slide 2). h = 0 never overestimates. The straight-line distance of a tile is ≤ its Manhattan distance (slides 22–25), which is admissible. But the number of <b>correctly</b> placed tiles is 8 at the goal (should be 0) and is large near the goal, so it overestimates — <b>not admissible</b>.","from":[{"s":"M23-3","qn":"Q1.3","pg":2}]},{"id":"M23-3-2","ch":4,"sl":"5, 11, 12, 19; ch3 32, 38","tp":"GBFS, BFS and A* with a self-loop","t":"short","q":"Consider the search space in the figure, where S is the start node and G satisfies the goal test. Arcs are labelled with their cost; the numbers on the nodes are the heuristic values. (A has a self-loop of cost 20.)<br>1. Apply greedy best-first search, breadth-first search and A* and give the expanded nodes, the path from start to goal (or none) and its cost. Children with the same cost go on the fringe in alphabetical order; repeated nodes are possible (tree search).<br>2. For each strategy, is the obtained solution optimal? Justify.","img":"M23-3-2.jpg","a":"1. <b>Greedy</b> (f = h): S → fringe A(4), B(10); expand A → A(4), D(7); A again → A(4)… it keeps expanding A forever. Expanded: S, A, A, A, … → <b>no solution</b>.<br><b>BFS</b> (FIFO): expanded S, A, B, A, D, C, A, D (then G is selected) → path <b>S-A-D-G</b>, cost 8 + 20 + 9 = <b>37</b>.<br><b>A*</b> (f = g + h): S(15) → A 8+4 = 12, B 9+10 = 19; expand A → A 28+4 = 32, D 28+7 = 35; expand B → C 10+7 = 17; expand C → D 14+7 = 21; expand D → G 23+0 = 23; select G. Expanded: S, A, B, C, D → path <b>S-B-C-D-G</b>, cost <b>23</b>.<br>2. • GBFS: <b>No</b> — greedy is not optimal (and here not even complete: it loops on A).<br>• BFS: <b>No</b> — 37 &gt; 23; BFS is optimal only when all step costs are equal.<br>• A*: <b>Yes</b> — h is admissible: h(S) = 15 ≤ 23, h(A) = 4 ≤ 29, h(B) = 10 ≤ 14, h(C) = 7 ≤ 13, h(D) = 7 ≤ 9, h(G) = 0.","e":"Informed search slide 5: greedy uses f = h; slide 11: greedy can get stuck in loops in tree search and is not optimal. Uninformed search slides 32 and 38: BFS expands level by level and is optimal only if all step costs are equal. Slides 12 and 19: A* uses f = g + h and is cost-optimal with an admissible heuristic (h(n) ≤ true remaining cost h*(n)).","from":[{"s":"M23-3","qn":"Q2","pg":3},{"s":"M23-3","qn":"Q2.2","pg":4}]},{"id":"Q23-1B-1-2","ch":4,"sl":"22–25","tp":"Manhattan distance of an 8-puzzle state","t":"mcq","q":"Consider the 8-puzzle in state s below. What is the Manhattan heuristic value h2(s)?<div class=\"tbl\" style=\"display:flex;gap:1.2rem;flex-wrap:wrap;align-items:flex-start\"><div><table class=\"mini\"><tr><td>1</td><td>3</td><td>5</td></tr><tr><td>6</td><td>&nbsp;</td><td>7</td></tr><tr><td>8</td><td>2</td><td>4</td></tr></table><div style=\"text-align:center;font-size:.85rem\">s</div></div><div><table class=\"mini\"><tr><td>1</td><td>3</td><td>8</td></tr><tr><td>6</td><td>2</td><td>&nbsp;</td></tr><tr><td>7</td><td>5</td><td>4</td></tr></table><div style=\"text-align:center;font-size:.85rem\">Goal</div></div></div>","o":["h2(s) = 20","h2(s) = 8","h2(s) = 13","h2(s) = 11"],"a":3,"e":"Slides 22–25: h2 = sum of the distances (in squares) of each tile from its goal square, ignoring the blank. Tiles: 1 → 0, 3 → 0, 5 → 3, 6 → 0, 7 → 2, 8 → 3, 2 → 1, 4 → 2. Total = 0+0+3+0+2+3+1+2 = <b>11</b>.","from":[{"s":"Q23-1B","qn":"Q1.2","pg":2}]},{"id":"Q23-1B-2","ch":4,"sl":"12, 19; ch3 40","tp":"UCS and A* with a self-loop and two goals","t":"short","q":"Consider the search space in the figure, where S is the start node and G1, G2 satisfy the goal test. Arcs are labelled with their cost; the numbers on the nodes are the heuristic values (h(G1) = h(G2) = 0). Apply UCS and A*: give the expanded nodes, the path solution and its cost. Children with the same cost go on the fringe in alphabetical order. Repeated nodes are possible.<br><small>Arcs: S→A 20, S→B 5, B→B 100, B→A 14, A→G1 30, A→G2 26 · h: S 20, A 25, B 20.</small>","img":"Q23-1B-2.jpg","a":"<b>UCS</b>: S(0) → A20, B5; B(5) → A19, B105; A(19) → G1 49, G2 45; A(20) → G1 50, G2 46; G2(45) is selected. Expanded <b>S, B, A, A</b> · path <b>S-B-A-G2</b> · cost 5 + 14 + 26 = <b>45</b>.<br><b>A*</b>: S (20) → A 20+25 = 45, B 5+20 = 25; B(25) → A 19+25 = 44, B 105+20 = 125; A(44) → G1 49, G2 45; G2(45) is selected (the model answer takes it before the tied A(45)). Expanded <b>S, B, A</b> · path <b>S-B-A-G2</b> · cost <b>45</b>.","e":"Uninformed search slide 40: UCS expands the lowest g(n); the self-loop on B (cost 100) never gets cheap enough to matter. Informed search slide 12: A* expands the lowest g + h. Both find the optimal 45.","nb":"At f = 45 A* has a tie between G2 and the second copy of A; the model answer stops at G2.","from":[{"s":"Q23-1B","qn":"Q2","pg":4}]},{"id":"F23-3-1A-1","ch":4,"sl":"12","tp":"g(n) vs h(n) in A*","t":"mcq","q":"What is the difference between the cost function g(n) and the heuristic function h(n) as the main parts of the A* evaluation function?","o":["g(n) returns the actual cost from current node to goal, h(n) returns the estimated cost from current node to goal.","g(n) returns the estimated cost from start node to current node, h(n) returns the estimated cost from current node to goal.","g(n) returns the actual cost from start node to current node, h(n) returns the estimated cost from current node to goal.","all the above"],"a":2,"e":"Slide 12: g(n) = <b>exact cost so far</b> to reach n (from the start), h(n) = <b>estimated</b> cost from n to the goal.","nb":"The marked copy circles (a); that is wrong — g(n) is the cost from the start to n, not from n to the goal.","from":[{"s":"F23-3","qn":"Q1 A.1","pg":1}]},{"id":"F23-3-1A-3","ch":4,"sl":"19, 22–24","tp":"Grid A*: Manhattan and straight-line both admissible","t":"mcq","q":"In the AI class project you have implemented A* for determining an optimal path in a grid environment. If diagonal moves are not allowed, which of the following is a correct statement?","o":["A* using the Manhattan distance as a heuristic will provide an optimal path, because the heuristic will never overestimate the cost to reach the goal.","A* using the straight-line distance as a heuristic will provide an optimal path, because the heuristic will never overestimate the cost to reach the goal.","Both a and b will provide an optimal path.","Both a and b will not provide an optimal path."],"a":2,"e":"Without diagonal moves every path needs at least |Δx| + |Δy| steps, so the Manhattan distance never overestimates (slides 22–24). The straight-line distance is even smaller (≤ Manhattan), so it is admissible too. Slide 19: with an admissible heuristic A* is cost-optimal → <b>both</b>.","from":[{"s":"F23-3","qn":"Q1 A.3","pg":1}]},{"id":"F23-3-1A-4","ch":4,"sl":"5","tp":"Greedy evaluation function","t":"mcq","q":"What is the heuristic function of greedy best-first search?","o":["f(n) = h(n) + g(n)","f(n) &lt; h(n)","f(n) = h(n)","f(n) &gt; h(n)"],"a":2,"e":"Slide 5: greedy best-first search uses the evaluation function <b>f(n) = h(n)</b>.","from":[{"s":"F23-3","qn":"Q1 A.4","pg":1}]},{"id":"M22A-1-P2","ch":4,"sl":"4–5, 12; ch3 32, 44","tp":"Fringe order of DFS, BFS, A*, GBFS","t":"short","q":"The search strategies seen in class store the leaf nodes of the search tree in memory in a specific order. Match each strategy (DFS, BFS, A*, GBFS) with its order:<br>A. increasing order of d(n), the depth of the node<br>B. decreasing order of d(n), the depth of the node<br>C. increasing order of h(n), the heuristic value<br>D. increasing order of h(n) + g(n)","a":"DFS → <b>B</b> (deepest first, LIFO)<br>BFS → <b>A</b> (shallowest first, FIFO)<br>A* → <b>D</b> (lowest g + h first)<br>GBFS → <b>C</b> (lowest h first)","e":"Uninformed search slide 32: BFS expands all nodes at depth i before depth i + 1; slide 44: DFS expands the deepest node. Informed search slide 4: best-first orders the fringe by f(n); slide 5: greedy f = h; slide 12: A* f = g + h.","from":[{"s":"F23-3","qn":"Q1 B","pg":1},{"s":"M22A","qn":"Q1 Part2","pg":2}]},{"id":"M22A-2","ch":4,"sl":"12–19","tp":"A* from Vaslui to Fagaras","t":"short","q":"Consider the road map in the figure (driving distances) and the table of straight-line distances <b>to Fagaras</b>. Find the driving route from <b>Vaslui to Fagaras</b> with A*.<br>1. Draw the A* tree-search.<br>2. Give the list of expanded nodes, the path solution and its cost.<br>3. Is the obtained solution optimal? Justify.","img":"M22A-2.jpg","a":"1–2. f = g + h:<br>• Vaslui (0+220 = 220) → Iasi 90+180 = <b>270</b>, Urziceni 140+190 = <b>330</b><br>• Iasi (270) → Neamt 180+140 = <b>320</b>, Vaslui 180+220 = 400<br>• Neamt (320) → Iasi 270+180 = 450<br>• Urziceni (330) → Bucharest 230+160 = <b>390</b>, Hirsova 240+260 = 500, Vaslui 280+220 = 500<br>• Bucharest (390) → Fagaras 410+0 = <b>410</b>, Pitesti 330+90 = 420, Giurgiu 320+200 = 520, Urziceni 320+190 = 510<br>• Vaslui (400) → Iasi 450, Urziceni 510<br>• Fagaras (410) is selected → goal.<br>Expanded: <b>Vaslui, Iasi, Neamt, Urziceni, Bucharest, Vaslui</b> · Path: <b>Vaslui → Urziceni → Bucharest → Fagaras</b> · Cost: <b>410</b>.<br>3. <b>Yes.</b> The straight-line distance never overestimates the road distance, so h is admissible, and A* with an admissible heuristic returns an optimal solution.","e":"Slide 12: A* expands the node with the lowest f(n) = g(n) + h(n); slides 13–18 show the same procedure on the Romania map. Slide 19: h<sub>SLD</sub> is admissible (never overestimates the actual road distance), and with an admissible h, A* is cost-optimal. In tree search, repeated states (Vaslui again) are allowed.","from":[{"s":"M22A","qn":"Q2","pg":3}]},{"id":"Q22-1-1-6","ch":4,"sl":"35","tp":"Main problem of hill climbing","t":"mcq","q":"The main problem of hill-climbing search is that:","o":["it requires huge memory","it requires a huge computational time","it can get stuck in local maxima (or minima)","the environment needs to be fully observable"],"a":2,"e":"Slide 35: <i>depending on the initial state, it can get stuck in local maxima</i>. Its advantages are very little memory and reasonable time (slide 29).","from":[{"s":"Q22-1","qn":"Q1.6","pg":2}]},{"id":"Q22-1-2","ch":4,"sl":"12; ch3 44–45","tp":"DFS and A* (directed graph)","t":"short","q":"Consider the search space in the figure, where S is the start node and G satisfies the goal test. Numbers on the edges are costs; the red numbers on the nodes are the heuristic values. Apply DFS and A*: give the expanded nodes, the path solution and its cost. Children with the same cost go on the fringe in alphabetical order.<br><small>Arcs: S→A 2, S→B 1, S→F 3, A→C 2, A→D 3, B→D 2, B→E 4, C→G 4, D→G 4, F→G 6 · h: A 4, B 5, C 2, D 2, E 8, F 4, G 0.</small>","img":"Q22-1-2.jpg","a":"<b>DFS</b> (alphabetical, deepest first): S → A → C → G. Expanded <b>S, A, C</b> · path <b>S-A-C-G</b> · cost 2 + 2 + 4 = <b>8</b>.<br><b>A*</b>: S → A 2+4 = 6, B 1+5 = 6, F 3+4 = 7; A(6) → C 4+2 = 6, D 5+2 = 7; B(6) → D 3+2 = 5, E 5+8 = 13; D(5) → G 7; C(6) → G 8; D(7) → G 9; F(7) → G 9; G(7) is selected. Expanded <b>S, A, B, D, C, D, F</b> · path <b>S-B-D-G</b> · cost <b>7</b>.","e":"Uninformed search slides 44–45: DFS expands the deepest node (LIFO) and stops at the first goal it reaches, ignoring costs. Informed search slide 12: A* expands the lowest f = g + h; ties go alphabetically, which is why D(7) and F(7) are expanded before G(7).","from":[{"s":"Q22-1","qn":"Q2","pg":3},{"s":"Q22-1","qn":"Q2 (key)","pg":4}]},{"id":"M22-1-1-3","ch":4,"sl":"19","tp":"Admissible: for every node","t":"mcq","q":"h is an admissible heuristic if","o":["There exists a node n such that h(n) ≤ h*(n).","For every node n: h(n) ≤ h*(n).","For every node, h(n) never underestimates the remaining cost from node n to the closest goal.","None"],"a":1,"e":"Slide 19: h is admissible if <b>for every node n</b>, h(n) ≤ h*(n) — it never <i>over</i>estimates. One node is not enough, and option C has the direction reversed.","from":[{"s":"M22-1","qn":"Q1.3","pg":2}]},{"id":"M22-1-1-4","ch":4,"sl":"19","tp":"Sum of admissible heuristics","t":"tf","q":"If h1 and h2 are admissible heuristics, then h3 = h1 + h2 is admissible.","a":1,"e":"Admissible means h ≤ h* (slide 19). Each of h1 and h2 can be as large as h*, so their sum can reach 2h* and overestimate. Example in the 8-puzzle: at a state one move from the goal, h1 = 1 and h2 = 1 (both exact) but h1 + h2 = 2 &gt; 1. <b>False</b>. (max(h1, h2) is admissible; slide 26.)","from":[{"s":"M22-1","qn":"Q1.4","pg":2}]},{"id":"M22-1-1-5","ch":4,"sl":"39","tp":"Beam search is incomplete","t":"tf","q":"Beam search is an incomplete searching algorithm.","a":0,"e":"Slide 39: beam search keeps only the best k nodes at each level, so it <i>may eliminate solutions even for finite search space graphs</i>. It is <b>incomplete</b> — <b>True</b>.","from":[{"s":"M22-1","qn":"Q1.5","pg":2}]},{"id":"M22-1-3","ch":4,"sl":"5, 12, 19; ch3 40","tp":"A*, UCS, greedy with an inadmissible h","t":"short","q":"Given the state space in the figure with the actual costs on the edges and the heuristic values inside the nodes (alphabetical tie-breaking):<br>a. For A*, uniform cost search and greedy best-first search, list the expanded nodes, the path solution and its cost.<br>b. Draw the tree-search of A*.<br>c. Is the solution returned by A* optimal? Why?","img":"M22-1-3.jpg","a":"a. <b>A*</b>: S (0+10) → A 2+7 = 9, B 4+5 = 9; tie → A → B 3+5 = 8, C 5+4 = 9; expand B(8) → G 8+0 = 8; select G. Expanded <b>S, A, B</b> · path <b>S-A-B-G</b> · cost <b>8</b>.<br><b>UCS</b>: S(0) → A2, B4; A(2) → B3, C5; B(3) → G8; B(4) → G9; C(5) → G7; select G(7). Expanded <b>S, A, B, B, C</b> · path <b>S-A-C-G</b> · cost <b>7</b>.<br><b>Greedy</b>: S → A(7), B(5); expand B → G(0); select G. Expanded <b>S, B</b> · path <b>S-B-G</b> · cost <b>9</b>.<br>b. S (f = 10) → A (9), B (9); A → B (8), C (9); B (8) → G (8).<br>c. <b>No</b> — the optimal cost is 7 (found by UCS). h is not admissible: h(A) = 7 &gt; h*(A) = 5 (A-C-G), h(C) = 4 &gt; h*(C) = 2, h(S) = 10 &gt; 7.","e":"Informed search slide 12: A* uses f = g + h; slide 5: greedy uses h only; slide 19: A* is guaranteed optimal only when h never overestimates the true remaining cost. Uninformed search slide 40: UCS expands the lowest g(n).","from":[{"s":"M22-1","qn":"Q3","pg":4},{"s":"M22-1","qn":"Q3 b–c","pg":5}]},{"id":"M25-3-2","ch":5,"sl":"18–24, 35, 56","tp":"Minimax and alpha-beta on a 4-level tree","t":"short","q":"Consider the game tree in the figure. The static evaluation values are shown below each leaf; the root is the MAX player and the search visits children left to right.<br>1. What move would the MINIMAX algorithm choose, and what is the backed-up value of that move?<br>2. Which nodes are <b>not examined</b> when α-β pruning is applied?","img":"M25-3-2.svg","a":"1. Backed-up values: E = 5, F = 6, G = 6, H = 7, I = 5, J = 8 (MAX nodes); B = min(5, 6) = 5, C = min(6, 7) = 6, D = min(5, 8) = 5 (MIN nodes); A = max(5, 6, 5) = <b>6</b>. MINIMAX chooses the move to <b>C</b>, with value <b>6</b>.<br>2. Not examined: <b>O, T, U, J, Y, Z</b>.<br>• At F (MAX, β = 5 from B): after N = 6, v = 6 ≥ β → O is pruned.<br>• At H (MAX, β = 6 from C): after S = 7, v = 7 ≥ β → T and U are pruned.<br>• At D (MIN, α = 6 from A): after I returns 5, v = 5 ≤ α → J and its leaves Y, Z are pruned.","e":"Slides 18–24: a MAX node takes the maximum of its children, a MIN node the minimum, backed up from the leaves. Slides 35 and 56 (alpha-beta): MAX only updates α, MIN only updates β, α and β are passed down to children, node values are passed up, and you prune as soon as α ≥ β.","from":[{"s":"M25-3","qn":"Q2","pg":2}],"aimg":"M25-3-2-ans.svg"},{"id":"F25-3-1-7","ch":5,"sl":"35, 56","tp":"Which values are pruned (5 6 | 7 3)","t":"mcq","q":"Given the tree in the figure (MAX root, two MIN children with leaves 5, 6 and 7, 3), what values are pruned with Alpha-Beta?","o":["No pruning","The value 3 is pruned","The value 6 is pruned","The value 7 is pruned"],"img":"F25-3-1-7.svg","a":0,"e":"Left MIN = min(5, 6) = 5 → root α = 5. Right MIN sees 7 (7 &gt; α, no cutoff), then 3 ≤ α — but 3 is its <b>last</b> child, so there is nothing left to prune. Every leaf is examined: <b>no pruning</b>. (If the leaves were 3, 7, the 7 would be pruned.)","from":[{"s":"F25-3","qn":"Q1.7","pg":2}]},{"id":"F25-3-1-8","ch":5,"sl":"69","tp":"Minimax vs alpha-beta relationship","t":"mcq","q":"Which of the following statements is true about the relationship between the Minimax algorithm and the Alpha-Beta pruning algorithm?","o":["Alpha-Beta pruning finds a different move than Minimax.","Alpha-Beta pruning always finds a worse move than Minimax.","Alpha-Beta pruning improves the speed of Minimax without changing the final result.","Alpha-Beta pruning ignores the utility values of nodes."],"a":2,"e":"Slide 69: alpha-beta computes the same root value as minimax, and pruning lets it search faster (deeper). <b>Same result, less work</b>.","from":[{"s":"F25-3","qn":"Q1.8","pg":2}]},{"id":"M25-2-1-4","ch":5,"sl":"32, 69","tp":"Purpose of alpha-beta","t":"mcq","q":"What is the main purpose of Alpha-Beta pruning in game algorithms?","o":["To generate the entire game search space","To increase average branching factor","To prune large parts of the search space","None of the above"],"a":2,"e":"Slide 32: alpha-beta is a way to improve the performance of minimax. Slide 70: minimax generates the entire search space, while <b>alpha-beta allows us to prune large parts of it</b> (slide 69: for Deep Blue it cut the average branching factor from 35–40 to 6).","from":[{"s":"M25-2","qn":"Q1.4","pg":4}]},{"id":"M25-2-1-5","ch":5,"sl":"72","tp":"Evaluation function","t":"mcq","q":"In the context of game playing, what is an evaluation function?","o":["A function that estimates the desirability of a game position","A function that guarantees the best move","A function that simulates opponent's moves","A function that determines the game's rules"],"a":0,"e":"Slides 72–73: an evaluation function says how good a board position is — it returns an <b>estimate</b> of the expected utility from a given position (like a heuristic estimates distance to the goal). It is only an estimate, so it does not guarantee the best move (slide 71: the guarantee of optimal play is gone).","from":[{"s":"M25-2","qn":"Q1.5","pg":4}]},{"id":"M25-2-1-7","ch":5,"sl":"18–21","tp":"Minimax value of the root","t":"mcq","q":"Consider the tree in the figure representing a zero-sum game, where player A is the MAX, and the leaf nodes represent the corresponding value of the utility function for the MAX player. What is the value of the node A after applying the MINIMAX algorithm?","o":["8","6","3","1"],"img":"M25-2-1-7.jpg","a":1,"e":"Levels: A = MAX, B and C = MIN, D–G = MAX. D = max(2, 3) = 3, E = max(4, 1) = 4, F = max(5, 6) = 6, G = max(7, 8) = 8. B = min(3, 4) = 3, C = min(6, 8) = 6. A = max(3, 6) = <b>6</b>. Slides 18–21: MAX picks the maximum child value, MIN the minimum, backed up from the leaves.","from":[{"s":"M25-2","qn":"Q1.7","pg":2}]},{"id":"M25-2-2B","ch":5,"sl":"35, 56","tp":"Alpha-beta with unknown leaf values","t":"short","q":"Consider the tree in the figure representing a zero-sum game (root = MAX, then MIN, then MAX), where A–F represent some values. The nodes are explored from left to right and alpha-beta pruning is used.<br>1. Give a value of A such that B is pruned.<br>2. Give a value of A such that B is NOT pruned.<br>3. Are there SOME values of A and B such that the subtree containing C and D is pruned? (True/False)<br>4. Assuming that B = 5 and A = 5, give a value of C and D such that the subtree containing E and F is pruned.","img":"M25-2-B.jpg","a":"The first MAX node returns max(5, 0) = 5, so the left MIN node has β = 5 when it visits its second MAX child.<br>1. B is pruned when the second MAX node reaches v ≥ β = 5 after A: any <b>A ≥ 5</b> (e.g. A = 7).<br>2. B is examined when <b>A &lt; 5</b> (e.g. A = 3).<br>3. <b>False.</b> C and D are under the first child of the right MIN node; that MAX node receives β = +∞, so it can never cut off, and the first child of a node is always examined.<br>4. With A = B = 5 the left MIN node = 5, so the root has α = 5. At the right MIN node, after its first child returns max(C, D), it prunes when max(C, D) ≤ α = 5. Any <b>C, D ≤ 5</b> works, e.g. C = 2, D = 3.","e":"Slide 35: at a MAX node cut off when α(n) ≥ β(n); at a MIN node cut off when β(n) ≤ α(n). Slide 56: MAX only updates α, MIN only updates β, α and β are passed down to the children, and node values are passed up. Start with α = −∞, β = +∞.","from":[{"s":"M25-2","qn":"Q2 B","pg":5}]},{"id":"F25-2-TF3","ch":5,"sl":"10","tp":"Zero-sum utilities are opposite","t":"tf","q":"Zero-sum games are the ones in which there are two agents whose actions must alternate and in which the utility values at the end of the game are always the same.","a":1,"e":"Slide 10: in a zero-sum game the agents have <b>opposite</b> utilities — one maximizes the value the other minimizes; if one wins the other loses. The end utilities are equal and opposite, not the same. <b>False</b>.","from":[{"s":"F25-2","qn":"Q2.3","pg":3}]},{"id":"F25-2-TF4","ch":5,"sl":"69","tp":"Alpha-beta never changes the root value","t":"tf","q":"Alpha-beta pruning can alter the computed minimax value of the root of a game search tree.","a":1,"e":"Slide 69: alpha-beta is <b>guaranteed to compute the same root value as minimax</b>. <b>False</b>.","from":[{"s":"F25-2","qn":"Q2.4","pg":3}]},{"id":"M25-1-3","ch":5,"sl":"35, 56, 69","tp":"Alpha-beta on a 3-ply tree","t":"short","q":"Consider the game tree in the figure; the static evaluation values are shown below each leaf node. The root is the MAX player and the search visits children left to right. Compute the minimax value using alpha-beta pruning (left-to-right evaluation) and indicate which branches were pruned.<br><small>(Node letters A–J are added for reference.)</small>","img":"M25-1-3.svg","a":"Root value = <b>3</b> (MAX moves to B).<br>• E = max(2, 3) = 3 → B has β = 3.<br>• F: first leaf 5 ≥ β = 3 → <b>prune F's second leaf (9)</b>; F = 5, so B = min(3, 5) = 3 → root α = 3.<br>• C: G = 0 ≤ α = 3 → <b>prune H</b> (leaves 6, 4); C = 0.<br>• D: I = max(2, 1) = 2 ≤ α = 3 → <b>prune J</b> (leaves 7, 5); D = 2.<br>Root = max(3, 0, 2) = 3.","e":"Slide 35: MAX cutoff when α(n) ≥ β(n), MIN cutoff when β(n) ≤ α(n). Slide 56: MAX updates only α, MIN updates only β; α, β go down to the children, values go up. Slide 69: alpha-beta always gives the same root value as minimax.","from":[{"s":"M25-1","qn":"Q3","pg":4}],"aimg":"M25-1-3-ans.svg"},{"id":"M24-3-1A-6","ch":5,"sl":"12","tp":"Game as a search problem","t":"mcq","q":"A game can be formally defined as a kind of search problem with the following components:","o":["Initial state","Successor function","Terminal test","All of the mentioned"],"a":3,"e":"Slide 12 (Game setup — games as search): initial state, successor function, terminal test and utility function. So <b>all of the mentioned</b>.","from":[{"s":"M24-3","qn":"Q1 A.6","pg":2},{"s":"M21-1","qn":"Q1.4","pg":2}]},{"id":"M24-3-2A","ch":5,"sl":"18–24, 35, 56","tp":"Minimax and alpha-beta on a 4-ply tree","t":"short","q":"Consider the game tree in the figure in which the first player is trying to maximize her score and the numbers at the leaves are the values returned by a static evaluator.<br>1. Fill in each triangle with the value returned by the standard Minimax algorithm.<br>2. Fill in each triangle with the value returned by the standard Alpha-Beta algorithm if the tree is processed from left to right, and mark the branches/nodes that would be pruned.<br><small>(Node letters are added for reference: B, C = MIN; D, E, F, G = MAX; H–N = MIN.)</small>","img":"M24-3-2A.svg","a":"1. Minimax: H = 3, I = 2, J = 15, K = 0, L = 2, M = 3, N = 2; D = 3, E = 15, F = 3, G = 2; B = 3, C = 2; root = <b>3</b>.<br>2. Alpha-beta (4 cutoffs):<br>• I (MIN, α = 3): first leaf 2 ≤ 3 → <b>prune 12</b>.<br>• E (MAX, β = 3): J = 15 ≥ 3 → <b>prune K</b> (25, 0).<br>• L (MIN, α = 3 from the root): leaf 2 ≤ 3 → <b>prune 5</b>.<br>• C (MIN, α = 3): F returns 3 ≤ 3 → <b>prune G</b> (and its subtree 2, 14).<br>Root value is still <b>3</b> (move to B).","e":"Slides 18–24: MAX takes the maximum, MIN the minimum of the children. Slide 35: cut off at a MAX node when α ≥ β and at a MIN node when β ≤ α. Slide 56: MAX updates α, MIN updates β; α and β travel down, values travel up. The model answer marks the same four cutoffs (0.5 mark each).","from":[{"s":"M24-3","qn":"Q2 A","pg":4}],"aimg":"M24-3-2A-ans.svg"},{"id":"M24-3-2B-1","ch":5,"sl":"69","tp":"Alpha-beta finds the minimax decision","t":"tf","q":"Minimax search with alpha-beta pruning may not find a minimax-optimal strategy.","a":1,"e":"Slide 69: alpha-beta is <b>guaranteed to compute the same root value as minimax</b>, so it always finds the minimax-optimal move. <b>False</b>.","from":[{"s":"M24-3","qn":"Q2 B.1","pg":5}]},{"id":"M24-3-2B-2","ch":5,"sl":"69","tp":"Move ordering and pruning","t":"tf","q":"Minimax with alpha-beta pruning will maximize the number of branches pruned if the moves under a node are ordered from best to worst.","a":0,"e":"Slide 69: good child ordering improves the effectiveness of pruning; with perfect ordering (best move first) the time drops to O(b<sup>d/2</sup>). <b>True</b>.","from":[{"s":"M24-3","qn":"Q2 B.2","pg":5},{"s":"M21-1","qn":"Q1.8","pg":3}]},{"id":"M24-3-2B-3","ch":5,"sl":"69–70","tp":"Alpha-beta is not slower than minimax","t":"tf","q":"The alpha-beta pruning algorithm generally requires more computation time than minimax without pruning on the same game tree.","a":1,"e":"Slide 69: in the worst case alpha-beta does no pruning and costs the same as minimax; otherwise it skips parts of the tree (slide 70: it prunes large parts of the search space). It never needs <i>more</i>. <b>False</b>.","from":[{"s":"M24-3","qn":"Q2 B.3","pg":5}]},{"id":"M24-3-2B-4","ch":5,"sl":"35, 56","tp":"Leftmost branch is never pruned","t":"tf","q":"When doing alpha-beta pruning on a game tree which is traversed from left to right, the leftmost branch will never be pruned.","a":0,"e":"Slides 35 and 56: search starts with α = −∞, β = +∞ and a cutoff needs a value already found among the siblings to the left. Down the leftmost path every node is a first child, so there is nothing to compare with yet — it is always explored. <b>True</b>.","from":[{"s":"M24-3","qn":"Q2 B.4","pg":5}]},{"id":"M24-3-2B-5","ch":5,"sl":"10","tp":"Zero-sum game: two players?","t":"tf","q":"A zero sum game has to be a two-player game as long as the condition for a zero sum game is satisfied.","a":0,"e":"Slide 10 describes zero-sum games as <i>agents with opposite utilities</i>: one value that one player maximizes and the other minimizes — if one player wins, the other necessarily loses. That framing is for two players, and the model answer marks the statement <b>True</b>.","nb":"The model answer says True. In general game theory a zero-sum game can also have more than two players; the slides only cover the two-player case.","from":[{"s":"M24-3","qn":"Q2 B.5","pg":5}]},{"id":"M24-3-2B-6","ch":5,"sl":"26","tp":"Minimax complexity = DFS","t":"tf","q":"The complexity of the minimax algorithm is the same as that of DFS.","a":0,"e":"Slide 26: minimax performs a complete <b>depth-first</b> exploration of the game tree — O(b<sup>m</sup>) time and O(bm) space, exactly DFS's complexity (uninformed search, slide 57). <b>True</b>.","from":[{"s":"M24-3","qn":"Q2 B.6","pg":5}]},{"id":"M24-1-2","ch":5,"sl":"18–24, 35, 56","tp":"Minimax and alpha-beta (negative values)","t":"short","q":"Consider the tree in the figure representing a zero-sum game (MAX at the root, then MIN, MAX, MIN); the squares are terminal nodes with the utility for the max player.<br>1. Apply the minimax algorithm for finding the best action for the max player at the root.<br>2. Apply the minimax algorithm with alpha-beta pruning for finding the best action for the max player at the root. Put X's through the branches/nodes that would be pruned.<br><small>(Node letters are added for reference.)</small>","img":"M24-1-3.svg","a":"1. MIN level: H = −2, I = −8, J = −3, K = −5, L = −4, M = −6, N = 1, O = −7.<br>MAX level: D = −2, E = −3, F = −4, G = 1.<br>MIN level: B = min(−2, −3) = −3, C = min(−4, 1) = −4.<br>Root = max(−3, −4) = <b>−3</b> → best action: go to <b>B</b> (left).<br>2. Pruned:<br>• At M (MIN, α = −3 from the root): first leaf −6 ≤ −3 → <b>prune the leaf 8</b>.<br>• F returns −4, so at C (MIN): −4 ≤ α = −3 → <b>prune G</b> with its whole subtree (N: 3, 1 and O: −7, 5).<br>Root value stays −3.","e":"Slides 18–24: back the values up level by level (MAX = maximum, MIN = minimum). Slide 35: at a MIN node cut off when β ≤ α; at a MAX node when α ≥ β. Slide 56: MAX updates α, MIN updates β, α and β are passed down.","from":[{"s":"M24-1","qn":"Q2","pg":3}],"aimg":"M24-1-3-ans.svg"},{"id":"F24-1-1B","ch":5,"sl":"12–13, 15, 27, 72","tp":"A game as a search problem","t":"short","q":"The goal is to formulate a two-player game (e.g. chess) as a searching problem. Choose the right answer for each part:<br>1. Initial state: (a) the current board of the game (b) any board of the game (c) empty board (d) none<br>2. Successor function: (a) all legal actions of the game (b) some specific actions to beat the opponent (c) some actions having a high cost (d) none<br>3. Goal state: (a) any state of the game (b) a well-defined set of states for which the game is over (c) an empty board (d) none<br>4. Evaluation function of a state: (a) a static heuristic function evaluating the quality of the board (b) the cost of the sequence of actions from the state to the goal state (c) a function depending on the initial state, the goal state and the state itself (d) all of the above<br>5. Solution for the game: (a) the optimal path from the initial state to the goal state (b) the best move to play (c) a state having a high evaluation function (d) all of the above","a":"1. <b>(a)</b> the current board — the root is the position in which a decision must be made.<br>2. <b>(a)</b> all legal actions (moves) of the game.<br>3. <b>(b)</b> the terminal states, where the game is over.<br>4. <b>(a)</b> a static heuristic function evaluating the quality of the board.<br>5. <b>(b)</b> the best move to play.","e":"Slide 12: games as search — initial state (board configuration), successor function = list of (move, state) pairs for the <i>legal</i> moves, terminal test (true when the game is over), utility function. Slide 13: the root is the position in which a decision must be made. Slide 72: the evaluation function says how good a board position is, based on static features of the board alone. Slide 27: in games we look for <b>one move only</b>, not a path.","from":[{"s":"F24-1","qn":"Q1 B","pg":1}]},{"id":"F24-1-1A-2","ch":5,"sl":"56, 69","tp":"Alpha-beta statements (all correct)","t":"mcq","q":"Which of the following statements are correct?","o":["Minimax and Alpha-beta pruning algorithms produce the same result (root value).","Alpha-beta bounds are initialized to negative and positive infinity respectively at the root node.","The primary purpose of Alpha-beta pruning is to save computation time by searching fewer nodes in the same tree.","Usually the Minimax algorithm is slower (time) than the Alpha-beta pruning algorithm.","All of the above"],"a":4,"e":"Slide 69: same root value as minimax, and pruning means fewer nodes → faster. Slide 56: start with α = −∞ and β = +∞. Every statement is true — <b>all of the above</b>.","from":[{"s":"F24-1","qn":"Q1 A.2","pg":2}]},{"id":"F24-1-2-3","ch":5,"sl":"27, 32","tp":"Alpha-beta finds a move, not a path","t":"tf","q":"The alpha-beta procedure is designed to improve the MAX-MIN procedure for finding the optimal path from the initial state to a closest goal state.","a":1,"e":"Slide 32: alpha-beta does improve minimax — but slide 27: game search looks for <b>one move only</b>, not a path to a goal (MAX cannot be sure how MIN will respond). <b>False</b>.","from":[{"s":"F24-1","qn":"Q2.3","pg":5}]},{"id":"Q23-2A-1-1","ch":5,"sl":"69, 71","tp":"NOT true about alpha-beta","t":"mcq","q":"Which of the following is NOT true for Alpha-beta pruning?","o":["It is generally (not always) faster than Minimax.","It is guaranteed to compute the same root value as Minimax.","It can reduce computation time by pruning portions of the game tree.","It loses the guarantee of optimality."],"a":3,"e":"Slide 69: alpha-beta is guaranteed to compute the same root value as minimax, prunes parts of the tree, and in the worst case does no pruning (so it is faster in general, not always). It does <b>not</b> lose optimality — that happens only when you cut the search off with an evaluation function (slide 71).","from":[{"s":"Q23-2A","qn":"Q1.1","pg":1}]},{"id":"Q23-2A-1-2","ch":5,"sl":"10","tp":"Zero-sum = competitive","t":"mcq","q":"A zero-sum game is:","o":["competitive","cooperative","the game in which all players can win at the same time.","All the above answers are correct."],"a":0,"e":"Slide 10: zero-sum games — agents have opposite utilities; adversarial, <b>pure competition</b>; if one player wins, the other necessarily loses.","from":[{"s":"Q23-2A","qn":"Q1.2","pg":1}]},{"id":"Q23-2A-1-3","ch":5,"sl":"27","tp":"Minimax performance depends on…","t":"mcq","q":"The performance of Minimax depends on:","o":["the depth of search","the quality of the evaluation function","the exploration order of the nodes","Answers (a) and (b) are correct."],"a":3,"e":"Slide 27: performance depends on <b>the quality of the evaluation function</b> (expert knowledge) and <b>the depth of search</b>. Node order only matters for alpha-beta pruning (slide 69), not for plain minimax.","from":[{"s":"Q23-2A","qn":"Q1.3","pg":1}]},{"id":"Q23-2A-1-4","ch":5,"sl":"69","tp":"Worst case of alpha-beta","t":"mcq","q":"In the worst case of the Alpha-beta algorithm:","o":["no pruning is made.","the time complexity is O(b<sup>d</sup>).","the time complexity is similar to the Minimax algorithm.","All the above answers are correct."],"a":3,"e":"Slide 69: <i>worst case: no pruning, same as minimax (O(b<sup>d</sup>))</i>. All three statements are true.","from":[{"s":"Q23-2A","qn":"Q1.4","pg":1}]},{"id":"Q23-2A-2","ch":5,"sl":"18–24, 35, 56, 69","tp":"Minimax with a leaf child; alpha-beta; ordering","t":"short","q":"Consider the game tree in the figure (MAX root with moves A, B, C, D; C leads directly to a terminal value 40).<br>1. Fill in each node with its Minimax value.<br>2. What is the best move for MAX? (A, B, C or D)<br>3. Apply alpha-beta pruning and show the pruned branches.<br>4. Is there a better node ordering that can improve the effectiveness of alpha-beta pruning? (Yes / No)","img":"Q23-2A-2.svg","a":"1. A = min(15, 18) = 15; E (MAX) = max(12, 48, 27) = 48; B = min(30, 48, 34) = 30; C = 40; D = min(20, 50) = 20; root = max(15, 30, 40, 20) = <b>40</b>.<br>2. <b>C</b>.<br>3. • At E (MAX, β = 30 from B): 12, then 48 ≥ 30 → <b>prune 27</b>.<br>• At D (MIN, α = 40 after C): 20 ≤ 40 → <b>prune 50</b>.<br>4. <b>Yes.</b> If the best move C were examined first (α = 40 right away), A would be cut after 15, B after its first child 30, and D after 20.","e":"Slides 18–24: back up values (MAX = max, MIN = min); a terminal child just passes its utility up. Slide 35: MAX cutoff α ≥ β, MIN cutoff β ≤ α. Slide 69: good move ordering (best first) increases the number of cutoffs.","from":[{"s":"Q23-2A","qn":"Q2","pg":2}],"aimg":"Q23-2A-2-ans.svg"},{"id":"F22-1-1-6","ch":5,"sl":"69","tp":"Minimax vs alpha-beta facts","t":"mcq","q":"Which of the following statements are correct?","o":["Minimax and Alpha-beta pruning algorithms produce the same result (root value).","Using Alpha-beta pruning instead of Minimax can double the solvable depth.","Usually the Minimax algorithm is slower (time) than Alpha-beta pruning.","All of the above answers are correct"],"a":3,"e":"Slide 69: alpha-beta is guaranteed to compute the same root value as minimax; with perfect ordering time drops to O(b<sup>d/2</sup>), which <i>doubles solvable depth</i>; and since it prunes, it is usually faster. <b>All of the above</b>.","from":[{"s":"F23-1","qn":"Q1.3","pg":1},{"s":"F22-1","qn":"Q1.6","pg":3}]},{"id":"M23-3-1-2","ch":5,"sl":"5, 10","tp":"Treasure hunt game type","t":"mcq","q":"A treasure hunting game is a game in which the winner is the player who gets the treasure first and the other players will be the losers. This game is:","o":["competitive","zero-sum","multi-agent environments","All the above answers are correct."],"a":3,"e":"Slide 5: games are multi-agent environments, and competitive ones give rise to adversarial search. Slide 10: in a zero-sum game the agents have opposite utilities — if one player wins, the others necessarily lose. The treasure hunt is all three: <b>all the above</b>.","from":[{"s":"M23-3","qn":"Q1.2","pg":2}]},{"id":"M23-3-3","ch":5,"sl":"18–24, 35, 56, 69","tp":"Minimax, alpha-beta and best move ordering","t":"short","q":"Consider the game tree in the figure (MAX root; MIN nodes A, B, C; MAX nodes below them; leaves at the bottom).<br>1. Fill in each box with the proper minimax value.<br>2. What is the best move for MAX (A, B or C)?<br>3. What score does MAX expect to receive?<br>4. Apply alpha-beta pruning on the tree and show the pruned branches.<br>5. Rearrange the leaves in a way that maximizes the number of pruned branches.","img":"M23-3-3.svg","a":"1. MAX nodes: A1 = 6, A2 = 9, A3 = 8 | B1 = 5, B2 = 5, B3 = 9 | C1 = 8, C2 = 9, C3 = 4, C4 = 9. MIN nodes: A = 6, B = 5, C = 4. Root = 6.<br>2. <b>A</b>. &nbsp;3. <b>6</b>.<br>4. • A2 (β = 6): first leaf 6 ≥ 6 → prune 1, 9.<br>• A3 (β = 6): 4, 3, then 8 ≥ 6 → prune 5.<br>• B (α = 6): B1 = 5 ≤ 6 → prune B2 and B3 (all their leaves).<br>• C2 (β = 8): 3, then 9 ≥ 8 → prune 5.<br>• C (α = 6): C3 = 4 ≤ 6 → prune C4 (7, 8, 9).<br>5. Put the best moves first: in every MAX node sort the leaves from high to low, and in every MIN node put the child with the smallest value first. One arrangement: A: (6 2) (8 5 4 3) (9 6 1) · B: (5 4) (5 4 3) (9 7 4 2) · C: (4) (8 2) (9 5 3) (9 8 7). Then A2 and A3 stop after their first leaf, B stops after B1, and C stops after its first child (4 ≤ 6), pruning everything else. (The model answer only sorts each MAX node's leaves from high to low: 6 2 | 9 6 1 | 8 5 4 3 | 5 3 | 5 4 3 | 9 7 4 2 | 8 2 | 9 5 3 | 4 | 9 8 7.)","e":"Slides 18–24: MAX nodes take the max and MIN nodes the min of their children. Slide 35: MAX cutoff when α ≥ β, MIN cutoff when β ≤ α. Slide 69: alpha-beta gives the same root value as minimax, and good child ordering (best first) improves pruning — with perfect ordering the cost drops to O(b<sup>d/2</sup>).","from":[{"s":"M23-3","qn":"Q3","pg":5}],"aimg":"M23-3-3-ans.svg"},{"id":"M22A-1-1","ch":5,"sl":"69","tp":"Alpha-beta = same move as minimax","t":"mcq","q":"The alpha–beta search algorithm computes ______________ minimax.","o":["the same optimal move as","better moves than","worse moves than","different moves than"],"a":0,"e":"Slide 69: alpha-beta is <b>guaranteed to compute the same root value as minimax</b> — it only skips nodes that cannot change the decision.","from":[{"s":"M22A","qn":"Q1 Part1.1","pg":2}]},{"id":"M22A-1-2","ch":5,"sl":"5","tp":"Adversarial = competitive","t":"mcq","q":"The environment of adversarial search problems is __________.","o":["Competitive","Cooperative","Deterministic","Fully observable"],"a":0,"e":"Slide 5: <i>competitive multi-agent environments give rise to adversarial search</i>. Games can also be stochastic or partially observable (slides 7, 9), so C and D are not what defines them.","from":[{"s":"M22A","qn":"Q1 Part1.2","pg":2}]},{"id":"M22A-1-3","ch":5,"sl":"18–22","tp":"Best score after choosing B","t":"mcq","q":"In the adversarial search shown in the figure, if Player 1 initially selects the move leading to position B (the left-hand branch), what is the maximum score Player 1 can achieve?","o":["4","6","1","11"],"img":"M22A-1-3.jpg","a":1,"e":"Player 1 = MAX at E and F: E = max(−2, 4) = 4, F = max(6, 2) = 6. Under B, Player 2 chooses between E (4) and F (6). The <b>maximum</b> Player 1 can reach on this branch is <b>6</b> (if Player 2 moves to F) — the model answer's choice. Against an optimal Player 2 (slide 22: MIN playing optimally), B's minimax value is min(4, 6) = 4, the guaranteed score.","nb":"Model answer: 6 (the best possible outcome). The minimax value of B, i.e. what Player 1 is guaranteed against optimal play, is 4.","from":[{"s":"M22A","qn":"Q1 Part1.3","pg":2}]},{"id":"M22A-3","ch":5,"sl":"18–24, 35, 56","tp":"Minimax and alpha-beta on an unbalanced tree","t":"short","q":"Consider the game tree in the figure (levels MAX, MIN, MAX, MIN, MAX; leaves appear at different depths).<br>1. What is the minimax value of the root node?<br>2. Apply alpha-beta pruning and show which move MAX will make.<br>3. Based on the MINIMAX algorithm, how many times will player MIN play?","img":"M22A-3.jpg","a":"1. Bottom-up: MIN(4, 2) = 2, MAX(1, 2) = 2; MIN(4, 3) = 3, MAX(5, 3) = 5; MIN node = min(2, 5) = 2; root = max(5, 2) = <b>5</b>.<br>2. Root takes the left leaf 5 → α = 5. Right MIN node (α = 5): its left MAX child sees leaf 1, then the MIN node (4, 2) gets 4 ≤ α = 5 → <b>prune the leaf 2</b>; the MAX child returns 4. Back at the MIN node: 4 ≤ α = 5 → <b>prune its whole right subtree</b> (5, MIN(4, 3)). MAX plays the <b>left move</b> (value 5).<br>3. <b>Zero</b> — MAX's best move leads straight to the terminal leaf 5, so MIN never gets to move.","e":"Slides 18–24: back up values (MAX = max, MIN = min); a leaf's value is its utility. Slide 35: MIN cutoff when β ≤ α. Slide 56: α and β are passed down to the children; values are passed up.","from":[{"s":"M22A","qn":"Q3","pg":4}]},{"id":"M22-2-1-1","ch":5,"sl":"17, 24, 37","tp":"What alpha-beta returns","t":"mcq","q":"The Alpha-Beta procedure returns:","o":["The best sequence of actions from the root to the leaf","The best move to play by the game.","The amount of points earned by the player.","None of above."],"a":1,"e":"Slide 37: ALPHA-BETA-SEARCH(state) <i>returns an action</i> — the successor with the best value. Slide 27: in games we are looking for <b>one move only</b>, not a whole path, because MAX cannot be sure how MIN will respond (slide 17).","from":[{"s":"M22-2","qn":"Q1.1","pg":1}]},{"id":"M22-2-1-2","ch":5,"sl":"69","tp":"Ideal ordering for alpha-beta","t":"mcq","q":"The ideal ordering for Alpha-Beta pruning occurs when","o":["The best moves occur at the left side of the tree.","The best move occurs on the right side of the tree.","Some best moves occur in both left and right side of the tree.","All of the above."],"a":0,"e":"Slide 69: good child ordering improves pruning; with <b>perfect ordering</b> — the best move examined first, i.e. on the left when the tree is traversed left to right — time drops to O(b<sup>d/2</sup>).","from":[{"s":"M22-2","qn":"Q1.2","pg":1}]},{"id":"M22-2-1-3","ch":5,"sl":"69","tp":"Minimax and alpha-beta: same move","t":"tf","q":"The Max-Min and alpha-beta procedures always return the same move.","a":0,"e":"Slide 69: alpha-beta is guaranteed to compute the same root value as minimax, so it chooses the same move. <b>True</b>.","from":[{"s":"M22-2","qn":"Q1.3","pg":1}]},{"id":"M22-2-2","ch":5,"sl":"35, 56","tp":"Alpha-beta on a 2-ply tree (2 3 5 9 0 1 7 5)","t":"short","q":"Apply the Alpha-Beta pruning algorithm to the tree in the figure. Mark the pruned branches and the best returned move.","img":"M22-2-2.svg","a":"• D = max(2, 3) = 3 → B has β = 3.<br>• E: first leaf 5 ≥ β = 3 → <b>prune the leaf 9</b>; B = 3 → root α = 3.<br>• F = max(0, 1) = 1 → at C: 1 ≤ α = 3 → <b>prune G</b> (7, 5).<br>Root value = <b>3</b>; best move = <b>A → B</b>.","e":"Slide 56: start with α = −∞, β = +∞; MAX updates α, MIN updates β; α and β are passed down, values passed up; prune when α ≥ β.","from":[{"s":"M22-2","qn":"Q2","pg":1}],"aimg":"M22-2-2-ans.svg"},{"id":"M21-1-1-5","ch":5,"sl":"18–24","tp":"Algorithm for win/lose decisions","t":"mcq","q":"Which algorithm is used in the game tree to make decisions of Win/Lose?","o":["Heuristic Search Algorithm","DFS/BFS algorithm","Greedy Search Algorithm","Min/Max algorithm"],"a":3,"e":"Slides 18–24: in a game tree the optimal decision comes from the <b>minimax</b> value of each node — MAX picks the maximum, MIN the minimum, backed up from the terminal (win/lose/draw) utilities.","from":[{"s":"M21-1","qn":"Q1.5","pg":2}]},{"id":"M21-1-1-6","ch":5,"sl":"32–33","tp":"Minimax that removes useless branches","t":"mcq","q":"The search algorithm which is similar to minimax search, but removes the branches that don't affect the final output, is known as ___.","o":["Depth-first search","Breadth-first search","Alpha-beta pruning","None of the above"],"a":2,"e":"Slides 32–33: <b>alpha-beta pruning</b> improves minimax by not computing nodes that, whatever their value, cannot affect the value of the root.","from":[{"s":"M21-1","qn":"Q1.6","pg":3}]},{"id":"M21-1-3","ch":5,"sl":"18–24, 35, 56","tp":"Minimax and alpha-beta on a 16-leaf tree","t":"short","q":"Consider the game tree in the figure in which the first player is trying to maximize her score; the numbers at the leaves are the values returned by a static evaluator.<br>(a) Fill in each box with the value returned by the standard minimax algorithm.<br>(b) Circle the best initial move for the first player.<br>(c) Fill in each box with the value returned by the standard alpha-beta algorithm (left to right). Cross out the leaves and non-leaf nodes that need not be examined.<br><small>(Node letters are added for reference.)</small>","img":"M21-1-3.svg","a":"(a) MIN level: H = 5, I = 2, J = 4, K = 2, L = 5, M = 1, N = 3, O = 2. MAX level: D = 5, E = 4, F = 5, G = 3. MIN level: B = 4, C = 3. Root = <b>4</b>.<br>(b) <b>Left</b> (to B, value 4).<br>(c) Not examined: <b>I's second leaf (6)</b> (2 ≤ α = 5 at I), <b>K's second leaf (2)</b> (2 ≤ α = 4), <b>M's second leaf (5)</b> (1 ≤ α = 5), <b>N's second leaf (9)</b> (3 ≤ α = 4), <b>O's second leaf (6)</b> (2 ≤ α = 4). Five leaves are pruned; the root value is still 4.","e":"Slides 18–24: back up values level by level. Slide 35: at a MIN node cut off as soon as β ≤ α. Slide 56: α and β are passed down to the children (here the α of the MAX parent reaches each MIN node at the bottom), values are passed up.","from":[{"s":"M21-1","qn":"Q3","pg":5},{"s":"M21-1","qn":"Q3 (sol.)","pg":6}],"aimg":"M21-1-3-ans.svg"},{"id":"M25-3-3A","ch":6,"sl":"4, 8–9, 12, 13","tp":"Formulate a CSP in extension (dialysis centers)","t":"short","q":"Four patients P1, P2, P3 and P4 must be assigned to dialysis medical centers A and B in Riyadh.<br>a. Each patient must be assigned only one center, either A or B.<br>b. P1 and P2 must be assigned to the same center (they travel together).<br>c. P3 and P4 must be assigned to different centers (they receive the same type of treatment).<br>d. If P1 and P3 are assigned to the same center, then P4 must be assigned to a different center.<br>1. Formulate this problem as a binary CSP: identify the variables, domains and constraints. The constraints must be given <b>in extension</b>.<br>2. Give a solution of the problem if there is one.","a":"1. <b>Variables</b>: X = {P1, P2, P3, P4}.<br><b>Domains</b>: D1 = D2 = D3 = D4 = {A, B} (this also covers rule a: one center each).<br><b>Constraints</b> (in extension):<br>C12 on (P1, P2): R12 = {(A, A), (B, B)}<br>C34 on (P3, P4): R34 = {(A, B), (B, A)}<br>Rule d is already implied by C34: if P1 = P3, then P4 ≠ P3 = P1, so it needs no extra constraint (written on its own it would be a 3-variable constraint, not binary). If you write it out, it is R134 on (P1, P3, P4) = all triples except (A, A, A) and (B, B, B).<br>2. Yes, e.g. <b>P1 = A, P2 = A, P3 = A, P4 = B</b> (also P1 = P2 = A, P3 = B, P4 = A, and the two mirror solutions with A and B swapped).","e":"Slides 4 and 8: a CSP is X (variables), D (domains), C (constraints), with R the allowed tuples. Slide 12: a constraint in <i>extension</i> lists the allowed tuples, like R<sub>xyz</sub> = {(a,a,a), (a,b,a), (b,a,b)}; slide 9 shows the same style for R14 and R34. Slide 13: a binary constraint involves two variables.","from":[{"s":"M25-3","qn":"Q3 A","pg":3}]},{"id":"M25-3-3B","ch":6,"sl":"10, 17, 57–59, 64–66, 74","tp":"Constraint graph, MRV, degree, arc consistency","t":"short","q":"Consider the CSP with 4 variables X1, X2, X3, X4.<br>Domains: D1 = {1, 2, 3}, D2 = {2, 3, 4}, D3 = {1, 2}, D4 = {1, 2, 3, 4}.<br>Constraints: C1: X2 ≤ X1 &nbsp; C2: X3 &gt; X2 &nbsp; C3: X4 ≤ X1 &nbsp; C4: X4 ≤ X2<br>1. Draw the constraint graph.<br>2. How many complete assignments does this CSP have?<br>3. Based on the minimum remaining values (MRV) heuristic, which variable(s) should be chosen first?<br>4. Based on the most constraining variable heuristic, which variable(s) should be chosen first?<br>5. Apply <b>arc consistency</b>. What do you conclude?","a":"1. One node per variable, one edge per binary constraint: <b>X1–X2</b> (C1), <b>X2–X3</b> (C2), <b>X1–X4</b> (C3), <b>X2–X4</b> (C4).<br>2. 3 × 3 × 2 × 4 = <b>72</b> complete assignments.<br>3. MRV picks the smallest domain: <b>X3</b> (2 values).<br>4. Degree heuristic picks the variable in the most constraints: <b>X2</b> (with X1, X3, X4 → degree 3; X1 and X4 have 2, X3 has 1).<br>5. Arc consistency:<br>• (X2, X1), X2 ≤ X1: X2 = 4 has no support → D2 = {2, 3}<br>• (X1, X2): X1 = 1 has no X2 ≤ 1 → D1 = {2, 3}<br>• (X3, X2), X3 &gt; X2: X3 = 1 and X3 = 2 need X2 &lt; 2, but D2 = {2, 3} → D3 = { } (<b>empty</b>)<br>An empty domain means the CSP has <b>no solution</b>.","e":"Slide 17: in the constraint graph, nodes are variables and a link joins two variables that share a constraint. Slide 10: n variables with domain sizes d<sub>i</sub> give ∏ d<sub>i</sub> complete assignments (d<sup>n</sup> when all are equal). Slide 57: MRV = most constrained variable (fewest legal values). Slides 58–59: most constraining variable = degree heuristic (most constraints on other unassigned variables). Slides 64–66 and 63: an arc X → Y is consistent if every value of X has a supporting value in Y; finding an empty domain proves there is no solution.","from":[{"s":"M25-3","qn":"Q3 B","pg":3},{"s":"M25-3","qn":"Q3 B (cont.)","pg":4},{"s":"M25-1","qn":"Q4 (parts 1–3)","pg":5}]},{"id":"F25-3-1-9","ch":6,"sl":"57–60","tp":"LCV definition","t":"mcq","q":"The Least Constraining Value (LCV) heuristic:","o":["Selects the value that rules out the fewest choices for the neighboring variables","Chooses the variable involved in the largest number of constraints with other unassigned variables","Selects the variable with the smallest domain","All of the above"],"a":0,"e":"Slide 60: LCV prefers the value that rules out the fewest choices for the neighbouring variables. Option B is the degree heuristic (slide 58) and option C is MRV (slide 57).","from":[{"s":"F25-3","qn":"Q1.9","pg":2}]},{"id":"F25-3-1-10","ch":6,"sl":"77","tp":"Forward checking: domain of B","t":"mcq","q":"Consider a CSP with variables A, B, C with domains A {1, 2}, B {1, 2}, C {1, 2} and constraints A ≠ B, B ≠ C. If A = 1 is assigned and <b>forward checking</b> is applied, what domain will B have?","o":["{1, 2}","{2}","{1}","{ }"],"a":1,"e":"Slide 77: after assigning A = 1, forward checking deletes from each unassigned neighbour of A the values inconsistent with it. B ≠ A removes 1 → <b>B = {2}</b>. (C is not a neighbour of A, so it is untouched.)","from":[{"s":"F25-3","qn":"Q1.10","pg":2}]},{"id":"M25-2-1-6","ch":6,"sl":"58","tp":"Reduce branching factor: degree heuristic","t":"mcq","q":"Which heuristic is commonly used in solving CSPs to reduce the branching factor on the choices for remaining variables?","o":["Least-Constraining-Value","Most-Constraining-Variable","Minimum-Remaining-Values","Maximum-Remaining-Values"],"a":1,"e":"Slide 58: the <b>most constraining variable</b> (degree heuristic) <i>attempts to reduce the branching factor on future choices</i> by selecting the variable involved in the largest number of constraints on other unassigned variables. MRV (slide 57) picks the variable with the fewest legal values; LCV (slide 60) orders values, not variables.","from":[{"s":"M25-2","qn":"Q1.6","pg":4}]},{"id":"M25-2-3","ch":6,"sl":"4, 8, 13, 28, 64","tp":"Magic square as a CSP","t":"short","q":"A pure magic square of 3×3 contains the digits 1 to 9 so that the sums along the rows, columns and both diagonals are equal. Complete this partially filled square:<div class=\"tbl\"><table class=\"mini\"><tr><td>2</td><td>A</td><td>4</td></tr><tr><td>B</td><td>C</td><td>D</td></tr><tr><td>6</td><td>E</td><td>8</td></tr></table></div>1. How many variables do we need to fill the square?<br>2. What is the domain of each variable?<br>3. Give a binary constraint between the variables A and E.<br>4. What is the value of A if we apply arc consistency on the arc (A, E)?<br>5. Perform a backtrack search for the remaining variables using alphabetic order for the variables and increasing values for the values.","a":"The magic sum of 1…9 is 45 / 3 = <b>15</b>.<br>1. <b>5 variables</b>: A, B, C, D, E.<br>2. Each variable takes one of the digits not yet used: <b>{1, 3, 5, 7, 9}</b> (all digits are different).<br>3. All digits differ, so <b>A ≠ E</b>. Also, the diagonal 2 + C + 8 = 15 forces C = 5, so the middle column gives <b>A + E = 10</b>.<br>4. Using A + E = 10 together with A ≠ E: A = 5 would need E = 5, which is not allowed, so 5 is removed → <b>A ∈ {1, 3, 7, 9}</b>. (With A ≠ E alone, nothing is removed.)<br>5. Backtracking, alphabetic order, increasing values (check each constraint once its variables are set):<br>A = 1, 3, 5, 7 ✗ (row 1: 2 + A + 4 ≠ 15) → <b>A = 9</b><br>B = 1, 3, 5 ✗ (column 1: 2 + B + 6 ≠ 15) → <b>B = 7</b><br>C = 1, 3 ✗ (diagonal 2 + C + 8) → <b>C = 5</b><br>D = 1 ✗ (column 3 / row 2) → <b>D = 3</b><br><b>E = 1</b> ✓ (row 3, column 2)<br>Solution: 2 9 4 / 7 5 3 / 6 1 8.","e":"Slides 4 and 8: a CSP = variables, domains, constraints. Slide 13: a binary constraint involves a pair of variables (here A ≠ E). Slide 64: an arc (X, Y) is consistent if every value of X has some allowed value in Y — values without support are removed. Slide 28: backtracking assigns one variable at a time (depth-first) and backtracks when a value violates a constraint.","nb":"Unanswered exam copy — the solution is ours. The expected answer to part 4 depends on which binary constraint you wrote in part 3.","from":[{"s":"M25-2","qn":"Q3","pg":3}]},{"id":"F25-2-TF5","ch":6,"sl":"10, 20, 28","tp":"Complete assignments at depth n = dⁿ","t":"tf","q":"Consider a general CSP with n variables of domain size d. We would like to use a search tree to solve the CSP, where all the complete assignments (and thus all the solutions) are leaf nodes at depth n. Then, the number of complete assignments is d<sup>n</sup>.","a":0,"e":"Slide 10: n variables with domain size d → d<sup>n</sup> complete assignments. Slides 20 and 28: if one variable is assigned per level, every complete assignment is a leaf at depth n and there are exactly d<sup>n</sup> of them. <b>True</b>.","from":[{"s":"F25-2","qn":"Q2.5","pg":3}]},{"id":"F22-1-1-3","ch":6,"sl":"57","tp":"MRV = most constrained variable","t":"mcq","q":"Choosing the variable with the minimum remaining values (MRV) heuristic is known as:","o":["Least constraining variable","Most constrained variable","Least constrained variable","None of the above"],"a":1,"e":"Slide 57: <b>most constrained variable</b> — choose the variable with the fewest legal values — is the minimum remaining values (MRV) heuristic.","from":[{"s":"F25-1","qn":"Q1.4","pg":1},{"s":"F22-1","qn":"Q1.3","pg":2}]},{"id":"M24-3-1B","ch":6,"sl":"4, 9, 12, 13","tp":"Flight scheduling as a CSP","t":"short","q":"A basic application of constraint programming is scheduling a set F of flights in a set of timeslots S. Small example: F = {f1, f2, f3, f4}, S = {t1, t2}.<br>X1. Flights f1 and f2 are flown by the same pilot.<br>X2. Some flight attendants are planned in both flights f3 and f4.<br>X3. Flights f3, f2, f4 are ensured by the same airplane.<br>X4. Flight f1 must be scheduled on timeslot t1.<br>1. The variables of the CSP correspond to: (a) S = {t1, t2} (b) F = {f1, f2, f3, f4} (c) the set of flights flown with the same pilot (d) none<br>2. The domains of the variables correspond to: (a) the set of pilots (b) the set of airplanes (c) S = {t1, t2} (d) none<br>3. Statement X2 can be formulated with the constraint: (a) R34 = {(t1,t2), (t2,t1)} (b) R34 = {(t1,t2), (t2,t1), (t2,t2)} (c) R34 = {(t1,t1), (t2,t2)} (d) none<br>4. The problem has a unary constraint: (a) X1 (b) X2 (c) X3 (d) X4","a":"1. <b>(b)</b> the flights F = {f1, f2, f3, f4} — each flight needs a timeslot.<br>2. <b>(c)</b> the timeslots S = {t1, t2}.<br>3. <b>(a)</b> R34 = {(t1, t2), (t2, t1)}: f3 and f4 share attendants, so they must be in different timeslots.<br>4. <b>(d)</b> X4 (f1 = t1) involves only one variable.","e":"Slide 4: a CSP has variables X, domains D (one per variable) and constraints C. Slides 9 and 12: a constraint in extension lists the allowed tuples. Slide 13: a unary constraint involves a single variable (e.g. SA ≠ green); binary constraints involve two.","from":[{"s":"M24-3","qn":"Q1 B","pg":3}]},{"id":"M24-3-3","ch":6,"sl":"10, 57–59, 64–66","tp":"Constraint graph X>Y>Z: MRV, degree, AC","t":"short","q":"Consider the CSP represented by the constraint graph in the figure: X ∈ {1, 2}, Y ∈ {1, 2}, Z ∈ {1, 2, 3}, with constraints X &gt; Y and Y &gt; Z.<br>1. How many complete assignments does this CSP have?<br>2. According to the Most Constraining Variable heuristic, which variables should be assigned first? Put them in order.<br>3. According to the Most Constrained Variable (MRV) heuristic, which variables should be assigned first?<br>4. Achieve arc consistency on this problem. What do you conclude? Justify.","img":"M24-3-3.jpg","a":"1. 2 × 2 × 3 = <b>12</b>.<br>2. <b>Y first</b> (it is in 2 constraints), then X or Z (1 constraint each).<br>3. <b>X or Y first</b> (2 values each), then Z (3 values).<br>4. • Arc X → Y (X &gt; Y): X = 1 has no smaller Y → delete (X, 1), X = {2}.<br>• Arc Y → X: Y = 2 needs X &gt; 2 → delete (Y, 2), Y = {1}.<br>• Arc Y → Z (Y &gt; Z): Y = 1 needs Z &lt; 1 → delete (Y, 1), Y = { }.<br>The domain of Y is <b>empty</b>, so the CSP has <b>no solution</b>.","e":"Slide 10: number of complete assignments = product of the domain sizes. Slide 57: MRV = fewest legal values; slides 58–59: most constraining = degree heuristic (most constraints on other variables). Slides 64–66: remove values with no support; an empty domain means no solution (slide 63).","from":[{"s":"M24-3","qn":"Q3","pg":6}]},{"id":"M24-1-3","ch":6,"sl":"4, 10, 28, 57–59, 63, 77, 79","tp":"X, Y, Z ∈ {a, b} all different: BT, FC, MAC","t":"short","q":"Consider the simple CSP: three variables X, Y and Z, where each variable can take either a or b as a value, such that no two variables have the same value.<br>1. Write the corresponding CSP (variables, domains, constraints).<br>2. The size of the search space of the CSP is?<br>3. Show the search tree for Backtrack Search, Forward Checking and Maintaining Arc-Consistency (variables and values in alphabetical order).<br>4. According to the search trees, the CSP has one solution (T/F)?<br>5. Add another variable T with domain {a, b, c} and one constraint Z ≠ T.<br>a. Do we have to resolve the new CSP to check whether it has a solution? Justify.<br>b. Which variable should be assigned first by the Most Constraining Variable heuristic?<br>c. Which variable should be assigned first by the Most Constrained Variable heuristic?","a":"1. Variables {X, Y, Z}; domains D<sub>X</sub> = D<sub>Y</sub> = D<sub>Z</sub> = {a, b}; constraints X ≠ Y, X ≠ Z, Y ≠ Z (each = {(a, b), (b, a)}).<br>2. 2<sup>3</sup> = <b>8</b> complete assignments.<br>3. <b>Backtracking</b>: X=a → Y=a ✗, Y=b → Z=a ✗, Z=b ✗ → back; X=b → Y=a → Z=a ✗, Z=b ✗; Y=b ✗ → fail.<br><b>Forward checking</b>: X=a → Y{b}, Z{b}; Y=b → Z{ } dead end. X=b → Y{a}, Z{a}; Y=a → Z{ } dead end → fail.<br><b>MAC</b>: X=a → Y{b}, Z{b}, then arc Y–Z: Y=b has no support in Z{b} → empty, dead end right after X=a. Same for X=b → fail.<br>4. <b>False</b> — all three trees fail, so the CSP has <b>no</b> solution.<br>5a. <b>No.</b> X, Y, Z alone already have no solution (3 variables, only 2 values, all different); adding T and Z ≠ T only adds a constraint, so the new CSP has no solution either.<br>5b. <b>Z</b> — it is in 3 constraints (X, Y, T); X and Y have 2, T has 1.<br>5c. <b>X, Y or Z</b> (tie, 2 values each); T has 3 values.","e":"Slide 4: CSP = (X, D, C); slide 10: d<sup>n</sup> complete assignments. Slide 28: backtracking checks each new value against the assigned variables. Slide 77: forward checking deletes inconsistent values from the unassigned neighbours after each assignment and backtracks when a domain becomes empty. Slides 62–63: maintaining arc consistency after each assignment detects failure even earlier. Slides 57–59: MRV = fewest values; most constraining = most constraints on other variables.","nb":"Unanswered exam copy — the solution is ours.","from":[{"s":"M24-1","qn":"Q3","pg":4},{"s":"M24-1","qn":"Q3.5 b–c","pg":5}]},{"id":"F24-1-1A-3","ch":6,"sl":"3–5, 10","tp":"Class scheduling = CSP","t":"mcq","q":"Consider the problem of preparing a schedule for a class of students. What type of problem is this?","o":["Constraint satisfaction problem","Adversarial search problem","Uncertainty problem","Logical inference problem"],"a":0,"e":"Slides 3–5: a CSP assigns values to variables so that all constraints are satisfied; slide 10 lists scheduling (with time limits) as a typical finite-domain CSP. Courses/sessions are the variables, timeslots the values, and clashes the constraints.","from":[{"s":"F24-1","qn":"Q1 A.3","pg":2}]},{"id":"F24-1-2-4","ch":6,"sl":"64","tp":"Definition of arc-consistent variable","t":"tf","q":"A variable in a CSP is arc-consistent if every value in its domain satisfies the variable's binary constraints.","a":0,"e":"Slide 64: <i>a variable in a CSP is arc-consistent if every value in its domain satisfies the variable's binary constraints</i>. <b>True</b>.","from":[{"s":"F24-1","qn":"Q2.4","pg":5}]},{"id":"M23-1-1B","ch":6,"sl":"4, 8","tp":"CSP elements: students and classrooms","t":"short","q":"Consider a CSP in which 6 students need to be assigned to 2 available classrooms. The capacity of each classroom is 4 students. Match each CSP element (A. Variables, B. Domain, C. Constraints, D. Solution) with one of:<br>1. The first 4 students in the first classroom and the remaining 2 students in the second classroom.<br>2. Students number in each classroom ≤ 4<br>3. Schools<br>4. Students<br>5. Classrooms","a":"A. Variables → <b>4</b> (Students)<br>B. Domain → <b>5</b> (Classrooms)<br>C. Constraints → <b>2</b> (at most 4 students per classroom)<br>D. Solution → <b>1</b> (a complete assignment that satisfies the capacity constraint)","e":"Slides 4 and 8: X = the variables (each student needs a classroom), D = their domains (the classrooms), C = the constraints (capacity ≤ 4), and a solution is a complete assignment satisfying all constraints.","from":[{"s":"M23-1","qn":"Q1 B","pg":3}]},{"id":"Q23-1A-2","ch":6,"sl":"57–60, 64–66, 77","tp":"5-variable CSP: MRV, degree, LCV, FC, AC","t":"short","q":"Consider the constraint graph in the figure (all domains {1, 2, 3, 4}). Constraints: A ≠ B, A &lt; D, E − A is odd, B &lt; E, E ≠ D, D &lt; C, E ≠ C.<br>1. Based on MRV, which variable(s) should be chosen first?<br>2. Based on the degree heuristic, which variable(s) should be chosen first?<br>3. Assume we start with B. Based on the least constraining value heuristic, which value(s) should be chosen?<br>4. Every variable has all values and we assign A = 1. What are the remaining domains after forward checking?<br>5. Show the domains after running arc consistency on the initial graph.","img":"Q23-1A-2.jpg","a":"1. All domains have 4 values → <b>any variable</b> (tie).<br>2. Degrees: E 4 (A, B, C, D), A 3, D 3, B 2, C 2 → <b>E</b>, then {A, D}, then {B, C}.<br>3. <b>B = 1</b>: it removes only A = 1 (A ≠ B) and E = 1 (B &lt; E) — the fewest values. Larger values of B remove more values of E.<br>4. Neighbours of A are B, D, E: B ≠ 1 → {2, 3, 4}; D &gt; 1 → {2, 3, 4}; E − 1 odd → E ∈ {2, 4}; C is untouched {1, 2, 3, 4}.<br>5. A &lt; D removes A = 4, D = 1; B &lt; E removes B = 4, E = 1; D &lt; C removes D = 4, C = 1, 2; then A &lt; D (D ≤ 3) removes A = 3. Result: <b>A {1, 2}, B {1, 2, 3}, C {3, 4}, D {2, 3}, E {2, 3, 4}</b>.","e":"Slide 57: MRV = fewest legal values. Slides 58–59: degree heuristic = most constraints with other unassigned variables. Slide 60: LCV = value that rules out the fewest choices in the neighbours. Slide 77: forward checking removes, from each unassigned neighbour, values inconsistent with the new assignment. Slides 64–66: arc consistency removes unsupported values and rechecks the neighbours of any variable that lost a value.","from":[{"s":"Q23-1A","qn":"Q2","pg":3}]},{"id":"F23-1-1-4","ch":6,"sl":"10","tp":"Letters a–z: discrete domain","t":"mcq","q":"If there is a task of assigning different characters from 'a' to 'z' to three variables x1, x2 and x3, then the domains of these variables are:","o":["discrete","continuous","infinite","All the above answers are correct"],"a":0,"e":"Slide 10: the simplest CSPs have <b>discrete, finite domains</b> — here 26 letters. They are not continuous (slide 11: real-valued times) and not infinite.","from":[{"s":"F23-1","qn":"Q1.4","pg":1}]},{"id":"M22-2-1-5","ch":6,"sl":"62–63, 72","tp":"Effects of arc consistency","t":"mcq","q":"Achieving arc-consistency on a CSP can lead to:","o":["A CSP without solution when an empty domain is found","A CSP with only one solution when only one value remains in each domain.","An easier CSP to solve with search.","All of the above are correct."],"a":3,"e":"Slide 63: arc consistency transforms the CSP into an equivalent, easier one by removing inconsistent values; an empty domain means no solution, and in some cases the CSP is solved. Slide 72: when every variable keeps exactly one value, AC solves the problem. <b>All of the above</b>.","from":[{"s":"F23-1","qn":"Q1.9","pg":1},{"s":"M22-2","qn":"Q1.5","pg":1}]},{"id":"M23-3-1-1","ch":6,"sl":"8","tp":"Solution of a CSP","t":"mcq","q":"A solution of a CSP is:","o":["A complete assignment satisfying all constraints.","A complete assignment satisfying some constraints.","A partial assignment violating few constraints.","All the above answers are correct."],"a":0,"e":"Slide 8: <i>a solution is a complete assignment satisfying all constraints</i>.","from":[{"s":"M23-3","qn":"Q1.1","pg":2}]},{"id":"M23-3-1-4","ch":6,"sl":"10","tp":"Number of complete assignments","t":"mcq","q":"A CSP with 4 variables and all domains of size 2 has ……… complete assignments.","o":["12","8","16","5"],"a":2,"e":"Slide 10: n variables with domain size d give d<sup>n</sup> complete assignments: 2<sup>4</sup> = <b>16</b>.","from":[{"s":"M23-3","qn":"Q1.4","pg":2}]},{"id":"M23-3-1-5","ch":6,"sl":"9, 19, 63","tp":"CSP may have one, many or no solution","t":"mcq","q":"A CSP problem may have:","o":["One solution","Many solutions","No solution","All the above"],"a":3,"e":"Slide 9 shows a CSP with two solutions, slide 19 the 3-queens CSP with <b>no</b> solution, and slide 63 notes that propagation may find one solution or an empty domain (no solution). So <b>all the above</b>.","from":[{"s":"M23-3","qn":"Q1.5","pg":2}]},{"id":"F23-3-1A-2","ch":6,"sl":"21, 62–63, 77","tp":"When AC-3 and forward checking run","t":"mcq","q":"Arc-Consistency (e.g., AC-3 and Forward Checking) is used to eliminate large (inconsistent) parts of the state space during...","o":["A preprocessor phase before search starts.","The search after each assignment.","a & b","None of the above"],"a":2,"e":"Slide 21: AC-3 runs <b>before</b> search, forward checking <b>during</b> search. Slide 62: arc consistency can be run as a preprocessor or after each assignment. So <b>both</b>.","from":[{"s":"Q23-2B","qn":"Q2.2","pg":2},{"s":"F23-3","qn":"Q1 A.2","pg":1}]},{"id":"M21-2-1-2","ch":6,"sl":"63","tp":"Empty domain after AC = no solution","t":"mcq","q":"Let P′, with an empty domain, be the CSP obtained after achieving arc consistency on a CSP P. Then we guarantee that P has","o":["One solution","No solution","Many solutions","None of the above"],"a":1,"e":"Slide 63: arc consistency transforms the CSP into an <i>equivalent</i> one; if an empty domain is found, there is <b>no solution</b>.","from":[{"s":"Q23-2B","qn":"Q2.4","pg":2},{"s":"M21-2","qn":"Q1.2","pg":2}]},{"id":"Q23-2B-1","ch":6,"sl":"19, 62–64, 77","tp":"3-queens CSP: FC, MAC, arc consistency","t":"short","q":"The 3-queens problem is formulated as a CSP P: Q = {Q1, Q2, Q3}, D1 = D2 = D3 = {c1, c2, c3}, C12 = {(c1, c3), (c3, c1)}, C13 = {(c1, c2), (c2, c1), (c2, c3), (c3, c2)}, C23 = {(c1, c3), (c3, c1)}.<br>a) With forward checking, if we assign c3 to Q1 at the root, what values remain for Q2 and Q3?<br>b) With Maintaining Arc Consistency, if we assign c3 to Q1 at the root:<br>&nbsp;&nbsp;b1. What values remain for Q2 and Q3?<br>&nbsp;&nbsp;b2. Should we (i) conclude the CSP has no solution, (ii) backtrack to explore the rest of the search space, (iii) assign a value to another variable, or (iv) stop the search?<br>c) Achieve arc consistency on P. What do we conclude?","a":"a) Q1 = c3: C12 keeps only (c3, c1) → <b>D2 = {c1}</b>; C13 keeps only (c3, c2) → <b>D3 = {c2}</b>.<br>b1) After forward checking, MAC also checks the arc Q2–Q3: Q3 = c2 has no partner in C23 with Q2 = c1 → <b>D2 = {c1}, D3 = ∅</b>.<br>b2) <b>(ii) backtrack</b> — the empty domain only shows that Q1 = c3 fails; Q1 = c1 or c2 has not been tried.<br>c) • C12: c2 appears in no pair → remove (Q1, c2) and (Q2, c2).<br>• C13 (Q1 now {c1, c3}): Q3 = c1 and c3 have no support → remove them, D3 = {c2}.<br>• C23: Q2 = c1 and c3 need Q3 ∈ {c3, c1}, but D3 = {c2} → remove both, <b>D2 = ∅</b>.<br>An empty domain → <b>P has no solution</b> (slide 19 confirms 3-queens has none).","e":"Slide 19: the 3-queens CSP and its relations, with no solution. Slide 77: forward checking removes values of unassigned neighbours inconsistent with the assignment. Slides 62–63: arc consistency propagates further, detects failure earlier, and an empty domain means no solution — as a preprocessor that proves P unsolvable, during search it only kills the current branch.","from":[{"s":"Q23-2B","qn":"Q1","pg":1}]},{"id":"Q23-2B-2-1","ch":6,"sl":"64","tp":"X = Y + 1 on {1, 3}","t":"mcq","q":"A CSP has two variables X, Y with the same domain D<sub>X</sub> = D<sub>Y</sub> = {1, 3} and the constraint X = Y + 1. The solution would be:","o":["It has no solution","{X = 3, Y = 1}","{X = 1, Y = 3}"],"a":0,"e":"X = Y + 1 needs (X, Y) ∈ {(2, 1), (4, 3)}, but 2 and 4 are not in the domains. Arc consistency (slide 64) removes every value → <b>no solution</b>.","from":[{"s":"Q23-2B","qn":"Q2.1","pg":2}]},{"id":"Q23-2B-2-3","ch":6,"sl":"6, 10","tp":"Class scheduling: graph colouring and CSP","t":"mcq","q":"Consider a problem of preparing a schedule for a class of students. This problem is a type of","o":["Graph Coloring Problem","Routing Problem","Constraint Satisfaction Problem","Both a and c"],"a":3,"e":"Scheduling is a CSP (slide 10 lists scheduling problems). It is also a graph-colouring problem: courses are nodes, conflicting courses are linked, and timeslots are the colours — exactly like map colouring (slide 6). Model answer: <b>both</b>.","from":[{"s":"Q23-2B","qn":"Q2.3","pg":2}]},{"id":"Q23-2B-2-5","ch":6,"sl":"12","tp":"Types of constraints","t":"mcq","q":"A CSP can involve:","o":["Temporal constraints","Geometrical constraints","Logical constraints","All of the above"],"a":3,"e":"Slide 12: constraint types — temporal (t<sub>i</sub> &gt; t<sub>k</sub> + d), geometric (distance(x, y) ≤ d), algebraic, logic, symbolic. <b>All of the above</b>.","from":[{"s":"Q23-2B","qn":"Q2.5","pg":2}]},{"id":"M22A-1-4","ch":6,"sl":"62–63","tp":"What arc consistency can do","t":"mcq","q":"Applying arc consistency can:","o":["detect failure early","find the solution","be done before starting the search process","all the above answers are correct"],"a":3,"e":"Slide 62: arc consistency aims to detect failure early, can be run as a preprocessor (before search), and sometimes the preprocessing solves the whole problem. Slide 63: it may find a solution or an empty domain. So <b>all of the above</b>.","from":[{"s":"M22A","qn":"Q1 Part1.4","pg":2}]},{"id":"M22A-4","ch":6,"sl":"17, 57–60, 64–66, 77","tp":"Five variables ≠: MRV, degree, LCV, AC, FC","t":"short","q":"Five variables X1…X5 with domains X1 {C}, X2 {B, C}, X3 {A, B, C}, X4 {A, B, C}, X5 {B, C}.<br>Constraints: X1 ≠ X2, X2 ≠ X3, X3 ≠ X4, X4 ≠ X5, X2 ≠ X4, X3 ≠ X5.<br>1. Draw the constraint graph.<br>2. Which variable(s) should be chosen first by MRV?<br>3. Which variable(s) should be chosen first by the most constraining variable heuristic?<br>4. Starting with X2, which value(s) should be chosen by the least constraining value heuristic?<br>5. Show the domains after running arc consistency on the initial graph.<br>6. Apply forward checking (variable order X1…X5, values A, B, C): show the remaining domains after each step and give the solution if there is one.","a":"1. Edges: X1–X2, X2–X3, X3–X4, X4–X5, X2–X4, X3–X5.<br>2. <b>X1</b> (1 value).<br>3. <b>X2, X3 or X4</b> (degree 3 each; X5 has 2, X1 has 1).<br>4. <b>B</b>: X2 = C would remove C from X1 (empty!), X3 and X4, while X2 = B only removes B from X3 and X4.<br>5. X2 ≠ X1 = C → X2 = {B}; then X3 ≠ B → {A, C}, X4 ≠ B → {A, C}. Result: X1 {C}, X2 {B}, X3 {A, C}, X4 {A, C}, X5 {B, C}.<br>6. • X1 = C → X2 {B}, X3 {A, B, C}, X4 {A, B, C}, X5 {B, C}<br>• X2 = B → X3 {A, C}, X4 {A, C}, X5 {B, C}<br>• X3 = A → X4 {C}, X5 {B, C}<br>• X4 = C → X5 {B}<br>• X5 = B → solution <b>X1 = C, X2 = B, X3 = A, X4 = C, X5 = B</b>.","e":"Slide 17: constraint graph = one node per variable, one link per constraint. Slide 57: MRV; slides 58–59: degree heuristic; slide 60: LCV prefers the value that rules out the fewest choices for the neighbours. Slides 64–66: arc consistency deletes values with no support. Slide 77: forward checking deletes, from each unassigned neighbour, the values inconsistent with the new assignment.","from":[{"s":"M22A","qn":"Q4","pg":5},{"s":"M22A","qn":"Q4 (cont.)","pg":6}]},{"id":"M22-2-1-4","ch":6,"sl":"10","tp":"CSP search space size","t":"mcq","q":"The size of the search space of a CSP with N variables and d values in each domain is:","o":["N<sup>d</sup>","N + d","d<sup>N</sup>","None of the above."],"a":2,"e":"Slide 10: n variables with domain size d → O(<b>d<sup>n</sup></b>) complete assignments.","from":[{"s":"M22-2","qn":"Q1.4","pg":1}]},{"id":"M22-2-3","ch":6,"sl":"17, 58, 64–65, 77","tp":"Colouring 5 squares: FC, AC, degree","t":"short","q":"Assign colours to the five squares of the board so that horizontally and vertically adjacent squares do not have the same colour. Two colours: red (R) and black (B). Five variables (the squares), values {R, B}.<div class=\"tbl\"><table class=\"mini\"><tr><td>2</td><td></td></tr><tr><td>1</td><td>5</td></tr><tr><td>3</td><td>4</td></tr></table></div>a. Every variable has both values and we assign 1 = R. What is the result of forward checking?<br>b. If every variable has both values and arc consistency is run, what are the resulting domains?<br>c. If you assign B to variable 5 and run arc consistency, what values remain for each variable? What does it represent?<br>d. According to the most constraining variable heuristic, which variable should be assigned first? Put them in order.","a":"Adjacent pairs: 1–2, 1–3, 1–5, 3–4, 4–5.<br>a. Forward checking removes R from the unassigned neighbours of 1 (2, 3, 5): <b>1 = {R}, 2 = {B}, 3 = {B}, 4 = {R, B}, 5 = {B}</b>.<br>b. <b>Nothing changes</b> — every value of R/B has a different colour available in each neighbour, so all domains stay {R, B}.<br>c. 5 = B → 1 = {R}, 4 = {R}; then 2 = {B}, 3 = {B} (3 ≠ 1 = R and 3 ≠ 4 = R). Result <b>1 = R, 2 = B, 3 = B, 4 = R, 5 = B</b> — one value each, which is a <b>solution</b>.<br>d. Degrees: 1 → 3; 3, 4, 5 → 2; 2 → 1. Order: <b>1</b>, then {3, 4, 5}, then <b>2</b>.","e":"Slide 77: forward checking deletes, from each unassigned neighbour, values inconsistent with the assignment. Slide 65: with ≠ constraints and two values per domain, arc consistency removes nothing until a variable is fixed (like the Australia map). Slides 58–59: degree heuristic = most constraints on other variables.","from":[{"s":"M22-2","qn":"Q3","pg":3}]},{"id":"M21-2-1-6","ch":6,"sl":"6–7, 18–19","tp":"Problems that can be modelled as CSPs","t":"mcq","q":"Which of the following problems can be modelled as a CSP?","o":["8-Puzzle problem","8-Queen problem","Map colouring problem","All of the mentioned above."],"a":3,"e":"Slides 6 and 18 (map colouring) and 7 and 19 (n-queens) are the slides' CSP examples. The 8-puzzle can also be written with variables (one per tile position) and constraints (all tiles different, final positions), so the expected answer is <b>all of the above</b>.","from":[{"s":"M21-2","qn":"Q1.6","pg":2}]},{"id":"M21-2-1-7","ch":6,"sl":"60","tp":"Least constraining value","t":"mcq","q":"In CSP, the heuristic that chooses the value that rules out the fewest values in the remaining variables is…","o":["Least constraining value","Most constraining variable","Minimum remaining values","None of them"],"a":0,"e":"Slide 60: the <b>least constraining value</b> heuristic prefers the value that rules out the fewest choices for the neighbouring variables. MRV and most-constraining-variable choose <i>variables</i>, not values.","from":[{"s":"M21-2","qn":"Q1.7","pg":2}]},{"id":"M21-2-2","ch":6,"sl":"17, 57, 64–66","tp":"5-variable CSP: graph, MRV, arc consistency","t":"short","q":"Consider the CSP with five variables X1…X5.<br>Domains: D1 {1, 2, 3, 4}, D2 {3, 4, 5, 8, 9}, D3 {2, 3, 5, 6, 7, 9}, D4 {3, 5, 7, 8, 9}, D5 {1, 2, 3, 4, 5}<br>Constraints: X1 ≥ X2 · X2 &gt; X3 or (X2 − 3) = 2 · X3 ≠ X4 · X4 ≤ X5<br>1. Draw the constraint graph.<br>2. Using MRV, which variable is chosen first?<br>3. Run the arc-consistency algorithm.","a":"1. A chain: <b>X1 – X2 – X3 – X4 – X5</b> (one edge per constraint).<br>2. <b>X1</b> (4 values; the others have 5 or 6).<br>3. • (X1, X2), X1 ≥ X2: X1 = 1, 2 have no support → X1 = {3, 4}<br>• (X2, X1): X2 = 5, 8, 9 exceed every X1 → X2 = {3, 4}<br>• (X3, X2), X2 &gt; X3 (X2 = 5 is gone): X3 = 5, 6, 7, 9 → X3 = {2, 3}<br>• (X4, X5), X4 ≤ X5: X4 = 7, 8, 9 → X4 = {3, 5}<br>• (X5, X4): X5 = 1, 2 → X5 = {3, 4, 5}<br>Final: X1 {3, 4}, X2 {3, 4}, X3 {2, 3}, X4 {3, 5}, X5 {3, 4, 5}. (X3 ≠ X4 removes nothing.)","e":"Slide 17: constraint graph — nodes are variables, links join variables in a constraint. Slide 57: MRV picks the variable with the fewest legal values. Slides 64–66: an arc X → Y is consistent if every value of X has a supporting value of Y; when X loses values, the arcs pointing into X are rechecked.","nb":"The model answer prints X3 = {2, 4}; 4 is not in D3, so it should read {2, 3}. The model answer also gave a bonus mark because the constraint \"(X2 − 3) = 2\" was ambiguous.","from":[{"s":"M21-2","qn":"Q2","pg":3}]},{"id":"Q21-2A-1","ch":6,"sl":"65, 77, 64–66","tp":"Colour 5 squares (Blackboard quiz)","t":"short","q":"Colour the five squares of the board (row 1: 1 2 3, row 2: 4 5 under 1 and 2) so that horizontally and vertically adjacent squares have different colours; two colours R and B.<br>1. If every variable has both values and arc consistency is run, what are the resulting domains?<br>2. How many possible values for each variable? &nbsp;3. How many variables?<br>4. If every variable has both values except variable 5 which has only B, what is the result of arc consistency?<br>5. If every variable has both values and we assign R to variable 1, what is the result of forward checking?","a":"Adjacent pairs: 1–2, 2–3, 1–4, 2–5, 4–5.<br>1. <b>None of the domains changes</b>.<br>2. <b>2 values</b> (R, B). &nbsp;3. <b>5 variables</b>.<br>4. 5 = B → 2 = R, 4 = R → 1 = B, 3 = B: <b>1 = {B}, 2 = {R}, 3 = {B}, 4 = {R}, 5 = {B}</b>.<br>5. 1 = R removes R from its neighbours 2 and 4: <b>1 = {R}, 2 = {B}, 3 = {R, B}, 4 = {B}, 5 = {R, B}</b>.","e":"Slide 65: with ≠ constraints and two values, arc consistency removes nothing at the start. Slides 64–66: once one domain shrinks to a single value, the removals propagate along the arcs. Slide 77: forward checking only removes values from the direct neighbours of the assigned variable.","from":[{"s":"Q21-2A","qn":"Q1–Q5","pg":1}]},{"id":"Q21-2B-1","ch":6,"sl":"58–59, 64–66","tp":"A, B, C, D ∈ {1,2,3}: degree heuristic, AC after A = 3","t":"short","q":"Consider the constraint graph in the figure: A, B, C, D ∈ {1, 2, 3}; constraints B ≥ A, A &gt; D, C ≠ A, B ≠ C, C ≠ D + 1, C ≠ D.<br>1. How many variables and values do you have?<br>2. If you assign 3 to A and run arc consistency, what values remain for each variable?<br>3. According to the most constraining variable heuristic, which variable should be assigned first? Put all variables in order.","img":"Q21-2B.jpg","a":"1. <b>4 variables with 3 values each</b>.<br>2. A = 3 → B ≥ 3 gives <b>B = 3</b>; A &gt; D gives D ∈ {1, 2}; C ≠ A gives C ∈ {1, 2}. C = 2 needs a D with D + 1 ≠ 2 and D ≠ 2, but D ∈ {1, 2} → C = 2 is removed, <b>C = 1</b>. Then C ≠ D removes D = 1 → <b>D = 2</b>. Result <b>B = 3, C = 1, D = 2</b>.<br>3. Counting constraints: C is in 4 (A, B and two with D), A in 3, D in 3, B in 2 → <b>{C}, {A, D}, {B}</b>.","e":"Slides 58–59: the most constraining (degree) heuristic picks the variable involved in the most constraints on other unassigned variables. Slides 64–66: arc consistency removes values without support and propagates the change to the neighbours.","nb":"Blackboard screenshots with the student's selected options; the arc-consistency and degree answers are verified above.","from":[{"s":"Q21-2B","qn":"Q1–Q3","pg":1}]}]};
